'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const I=(n,cls='')=>'<svg class="icon '+cls+'" data-icon="'+E(n)+'" viewBox="0 0 24 24" aria-hidden="true">'+(n==='more'?'<g fill="currentColor" stroke="none"><circle cx="6" cy="12" r="1.8"/><circle cx="12" cy="12" r="1.8"/><circle cx="18" cy="12" r="1.8"/></g>':n==='grip'?'<g fill="currentColor" stroke="none">'+[6,12,18].flatMap(y=>[9,15].map(x=>'<circle cx="'+x+'" cy="'+y+'" r="1.4"/>')).join('')+'</g>':'<path d="'+(ICON_PATHS[n]||ICON_PATHS.file)+'"/>')+'</svg>';
const B=(label,act,cls='',attrs='')=>'<button type="button" class="btn '+cls+'" data-action="'+act+'" '+attrs+'>'+label+'</button>';
const A=(label,act,attrs='')=>'<button type="button" class="link" data-action="'+act+'" '+attrs+'>'+label+'</button>';
const tag=(s,c='')=>'<span class="tag '+c+'">'+E(s)+'</span>';
const ficon=d=>'<span class="fileicon '+d.type.toLowerCase()+'">'+E(d.type)+'</span>';
const file=id=>state.docs.find(d=>d.id===id);
const tool=id=>TOOLS.find(t=>t.id===id);
const selectedDocs=ids=>{const index=new Map(state.docs.map(d=>[d.id,d]));return ids.map(id=>index.get(id)).filter(Boolean);};
const storageKey='audit-studio-prototype-v1';
let state={docs:structuredClone(DOCS),tasks:[],templates:[],work:{},uploads:[],space:'项目空间',folder:'全部资料',librarySelected:[],stopwords:['的','和','以及'],newwords:[],view:'library',toolId:'extract',query:'',page:1,taskQuery:'',taskStatus:'all',taskTool:'all',taskPage:1};
try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved)state={...state,...saved,view:'library',query:'',page:1};}catch{}
(state.customFolders||[]).forEach(f=>{if(!FOLDERS.includes(f))FOLDERS.push(f);});
state.tasks.forEach(t=>{if(t.status==='running'&&!t.demoSnapshot){t.status='stopped';t.phase='任务已中断，可重新执行';}});
let modal=null,modalData={},opener=null,toastTimer,runTimers={},manage=false,manageIds=[],taskChecked=[],resultFilter='',resultScope='all',fullResult=false,configExpanded=false;
function persist(){try{localStorage.setItem(storageKey,JSON.stringify({docs:state.docs,tasks:state.tasks,taskDemoVersion:state.taskDemoVersion,templates:state.templates,work:state.work,uploads:state.uploads,customFolders:state.customFolders,space:state.space,folder:state.folder,stopwords:state.stopwords,newwords:state.newwords}));}catch{toast('浏览器存储不可用，本次修改仅在页面停留期间保留。');}}
function ws(id=state.toolId){if(!state.work[id]){const t=tool(id);state.work[id]={ids:[],preview:null,taskId:null,tab:'preview',subtab:id==='meeting'?'regular':'main',config:{template:id==='extract'?'':t.template,prompt:'请依据所选资料，'+t.desc+'。保留原文引用；未提取到的内容如实标注，不补充资料外事实。',fields:id==='extract'?[]:[...(t.fields||[])],checks:[...(t.checks||[])],merge:true,top:30,mode:'file',failure:'none',stageFailure:'none',secondTemplate:t.id==='theme'?'审计事项共同主题归纳':'主子项目关系识别',contractDataTemplate:'合同基础信息提取',bidTenderTemplate:'招标条件与评分检查',bidBidTemplate:'投标响应完整性检查',bidJointTemplate:'招投标联合对照检查',contractType:'采购合同',feeType:'工程监理服务费',mapName:'项目名称',mapUnit:'建设单位',mapAmount:'计划投资（万元）',mapBName:'项目名称',mapBUnit:'实施单位',mapBAmount:'安排资金（万元）',threshold:4,perfectThreshold:5,lockStrategy:'保留全部候选',compareRules:[{name:'项目名称',type:'文本相似',weight:0.6,threshold:4},{name:'建设 / 实施单位',type:'精确匹配',weight:0.3,threshold:5},{name:'投资金额（万元）',type:'数值比较',weight:0.1,threshold:4}],weightName:0.6,weightUnit:0.4,matchMode:'standard',cap:20,base:'',chunk:2000,overlap:200},projects:[{id:'p1',name:'设备采购项目',tender:[],bidders:[{name:'青禾公司',files:[]},{name:'远川公司',files:[]}]}],modes:['joint'],tableA:null,tableB:null,tableAName:'待查项目表',tableBName:'对照项目表',chats:[]};}return state.work[id];}
function currentTask(){return state.tasks.find(t=>t.id===ws().taskId);}
function currentConfig(){const t=currentTask();return t&&t.status!=='stopped'?t.config:ws().config;}
function isLocked(){return !!currentTask()&&currentTask().status!=='stopped';}
function toast(text,undo){clearTimeout(toastTimer);const node=$('#toast');node.innerHTML='<span>'+E(text)+'</span>'+(undo?'<button type="button" id="undo-toast">撤销</button>':'');node.classList.add('show');if(undo)$('#undo-toast').onclick=()=>{undo();node.classList.remove('show');};toastTimer=setTimeout(()=>node.classList.remove('show'),4500);}
function nav(view,id){configExpanded=false;state.view=view;if(id)state.toolId=id;manage=false;manageIds=[];resultFilter='';resultScope='all';fullResult=false;location.hash=view==='tool'?'tool/'+state.toolId:view;render();}
function route(){const [v,id]=(location.hash.slice(1)||'library').split('/');if(v==='tool'&&tool(id)){state.view='tool';state.toolId=id;}else if(['library','tasks','templates'].includes(v))state.view=v;else state.view='library';render();}
window.addEventListener('hashchange',route);
function render(){const compact=state.view==='tool';$('#app').innerHTML='<div class="shell '+(compact?'compactnav':'')+'">'+sidebar()+'<div class="content">'+topbar()+'<main id="main" tabindex="-1">'+(state.view==='library'?library():state.view==='tasks'?tasksPage():state.view==='templates'?templatesPage():workbench())+'</main></div></div>';persist();}
function sidebar(){return '<aside class="sidebar" aria-label="主要导航"><button class="brand" data-action="nav-library" title="返回资料管理"><span class="brandmark">'+I('layers')+'</span><span class="brand-text"><b>文档挖掘助手</b><small>AUDIT WORKSPACE</small></span></button>'+[['library','folder','资料管理'],['tasks','tasks','任务中心'],['templates','book','我的模板']].map(([id,ic,name])=>'<button class="navbtn '+(state.view===id?'active':'')+'" data-action="nav-'+id+'" title="'+name+'">'+I(ic)+'<span class="nav-label">'+name+'</span>'+(id==='tasks'&&state.tasks.some(t=>t.status==='running')?'<span class="badge-count">进行中</span>':'')+'</button>').join('')+['基础分析','审计专题','数据核对'].map(g=>'<div class="navgroup">'+g+'</div>'+TOOLS.filter(t=>t.group===g).map(t=>'<button class="navbtn '+(state.view==='tool'&&state.toolId===t.id?'tool-active':'')+'" data-action="open-tool" data-id="'+t.id+'" title="'+t.name+'">'+I(t.icon)+'<span class="nav-label">'+t.name+'</span></button>').join('')).join('')+'<div class="sidebar-bottom"><button class="navbtn" data-action="help" title="使用说明">'+I('help')+'<span class="nav-label">使用说明</span></button><div class="user row"><span class="avatar">审</span><div>审计工作空间<small class="muted" style="display:block;margin-top:4px">审计工作空间</small></div></div></div></aside>';}
function topbar(){return '<header class="topbar"><div class="row">'+B(I('menu'),'mobile-nav','ghost mobile-menu','aria-label="打开导航"')+'<div class="crumb"><span>审计智能工作台</span>'+I('chevron','icon-sm')+'<b>'+(state.view==='tool'?E(tool(state.toolId).name):state.view==='tasks'?'任务中心':state.view==='templates'?'模板管理':'文档资料挖掘')+'</b></div></div><div class="row gap16"><span class="demo-tag"><i class="dot"></i>交互 · 分析结果</span>'+A('<span class="helptext">操作指引</span>'+I('help','icon-sm'),'help')+'<span class="avatar no-mobile">审</span></div></header>';}
function docsIn(space,folder,query=''){return state.docs.filter(d=>!d.deleted&&d.space===space&&(folder==='全部资料'||d.folder===folder||d.folder.startsWith(folder+'/'))&&d.name.toLowerCase().includes(query.toLowerCase()));}
function library(){let docs=docsIn(state.space,state.folder,state.query),total=docs.length;state.page=Math.min(state.page,Math.max(1,Math.ceil(total/7)));const pageDocs=docs.slice((state.page-1)*7,state.page*7);const folders=state.space==='项目空间'?FOLDERS:state.space==='个人空间'?['全部资料','我的资料']:['全部资料','制度资料'];return '<div class="page"><div class="pagehead"><div><div class="eyebrow">DOCUMENT INTELLIGENCE</div><h1>资料管理</h1><p>选好资料，开始一次有依据的分析。</p></div><div class="row">'+B(I('clock')+'上传记录','upload-records')+B(I('upload')+'上传资料','upload','primary')+'</div></div><section class="welcome"><div><h2>从一份资料，到一条清晰的审计线索</h2><p>选择文件后使用右侧工具，或先选工具再添加资料。每项结果都可以回到原文核验。</p><div class="row mt">'+tag('11 项分析工具','blue')+'<span class="small muted">资料整理 → 分析执行 → 原文核验</span></div></div><div class="row gap16"><div class="welcome-art"><span class="art-file">'+I('file')+'</span>'+I('arrow')+'<span class="art-file">'+I('scan')+'</span></div>'+B('体验完整流程 '+I('arrow'),'quick-start','soft')+'</div></section><div class="library-layout"><section class="card"><div class="cardhead"><div class="row">'+I('folder')+'<h3>文档资料</h3></div>'+B(E(state.space)+' · '+(state.space==='个人空间'?'我的空间':state.space==='公共空间'?'市审计局':'园区改造项目')+I('down','icon-sm'),'space','sm')+'</div><div class="library-body"><nav class="folder-tree" aria-label="资料目录"><h4>资料目录</h4>'+folders.map(f=>'<button class="folderbtn '+(f===state.folder?'active':'')+'" data-action="folder" data-id="'+E(f)+'">'+I('folder')+f+'</button>').join('')+B(I('plus','icon-sm')+'新建目录','new-folder','ghost sm mt')+'</nav><div class="file-pane"><div class="toolbar"><span class="section-meta">'+E(state.folder)+' <span style="color:#bec8d4">/</span> '+total+' 份</span><div class="search">'+I('search')+'<input aria-label="搜索资料名称" placeholder="搜索文件名称" value="'+E(state.query)+'" data-input="library-query"></div></div>'+(state.librarySelected.length?'<div class="selectionbar"><span>已选 <b>'+state.librarySelected.length+'</b> 份 · 跨目录保留</span><div class="row">'+A('查看已选','library-selected')+A('清空','library-clear')+'</div></div>':'')+'<div class="tablewrap"><table class="table"><thead><tr><th style="width:35px"><input type="checkbox" aria-label="选择本页全部资料" data-change="library-page" '+(pageDocs.length&&pageDocs.every(d=>state.librarySelected.includes(d.id))?'checked':'')+'></th><th>文件名称</th><th>状态</th><th class="no-mobile">大小</th><th>操作</th></tr></thead><tbody>'+pageDocs.map(d=>'<tr><td><input type="checkbox" aria-label="选择 '+E(d.name)+'" data-change="library-check" data-id="'+d.id+'" '+(state.librarySelected.includes(d.id)?'checked':'')+' '+(d.local?'disabled':'')+'></td><td><div class="row">'+ficon(d)+'<div><button class="filename" data-action="source" data-id="'+d.id+'">'+E(d.name)+'</button><div class="file-sub">'+E(d.folder)+' · '+E(d.date)+'</div></div></div></td><td>'+tag(d.local?'等待解析':'可分析',d.local?'amber':'green')+'</td><td class="muted no-mobile">'+E(d.size)+'</td><td><div class="row gap6">'+A('预览','source','data-id="'+d.id+'"')+'<button class="iconbtn" data-action="file-detail" data-id="'+d.id+'" aria-label="'+E(d.name)+' 更多操作">'+I('settings','icon-sm')+'</button></div></td></tr>').join('')+'</tbody></table></div>'+(total===0?empty('没有找到资料','可以调整搜索条件，或向当前目录上传文件。','清除筛选','clear-library','folder'):'')+'<div class="pagination"><span>显示 '+(total?(state.page-1)*7+1:0)+'–'+Math.min(state.page*7,total)+' / '+total+' 份</span><div class="row">'+B('上一页','lib-prev','sm',state.page===1?'disabled':'')+'<span>'+state.page+' / '+Math.max(1,Math.ceil(total/7))+'</span>'+B('下一页','lib-next','sm',state.page*7>=total?'disabled':'')+'</div></div></div></div></section><aside class="card tools-panel"><div class="cardhead"><div><h3>选择分析工具</h3><p class="hint">从你要完成的审计任务开始</p></div>'+I('spark')+'</div>'+['基础分析','审计专题','数据核对'].map(g=>'<div class="tool-group-title">'+g+'</div>'+TOOLS.filter(t=>t.group===g).map(t=>'<button class="tool-card" data-action="open-tool" data-id="'+t.id+'"><span class="tool-symbol">'+I(t.icon)+'</span><span class="grow"><h4>'+t.name+'</h4><p>'+t.desc+'</p></span>'+I('chevron','chev')+'</button>').join('')).join('')+'</aside></div><div class="footer-hint">所有文件与分析结果均为，仅用于交互评审；不连接真实审计后台。</div></div>';}
function empty(title,text,label,act,icon='scan'){return '<div class="empty"><div class="empty-icon">'+I(icon)+'</div><h3>'+title+'</h3><p>'+text+'</p>'+(label?B(label,act,'primary mt'):'')+'</div>';}
function workbench(){const t=tool(state.toolId),w=ws(),task=currentTask();const phase=task?(task.status==='running'?1:2):w.ids.length?1:0;return '<div class="'+(fullResult?'full-result':'')+'"><header class="workhead"><div class="row between"><div class="row gap16"><span class="tool-symbol" style="width:43px;height:43px">'+I(t.icon)+'</span><div><h1>'+t.name+'</h1><p>'+t.desc+'。'+(t.id==='prepaid'?'此工具用于按合同约定计算费用。':'')+'</p></div></div><div class="row">'+B(I('back')+'资料管理','nav-library','ghost')+B(I('tasks')+'任务中心','nav-tasks','')+'</div></div><div class="steps">'+t.steps.map((s,i)=>(i?'<i class="step-line"></i>':'')+'<span class="step '+(i===phase?'active':i<phase?'done':'')+'"><span class="step-n">'+(i<phase?'✓':i+1)+'</span>'+s+'</span>').join('')+'<span class="grow"></span><span class="no-mobile">输入：'+t.input+'　·　输出：'+t.output+'</span></div></header><div class="workbench">'+(t.id==='association'?associationSidebar():workset())+'<section class="workarea">'+(task?taskArea(task):t.id==='bidding'?biddingPreparation():t.id==='association'?associationPreparation():preparation())+'</section>'+((t.id==='association'||(task&&!configExpanded))?'':configPanel())+'</div></div>';}
function workset(){const w=ws(),t=tool(state.toolId),task=currentTask();let ids=task?task.ids:w.ids;const docs=selectedDocs(ids);const folders=[...new Set(docs.map(d=>d.folder))];return '<aside class="workset"><div class="workset-top"><div class="row between mb"><h3>本次资料 <span class="muted small">'+ids.length+'</span></h3>'+(!isLocked()&&ids.length?A(manage?'完成':'批量管理','manage'):'')+'</div>'+B(I('plus')+'添加文件','picker','w100 '+(ids.length?'':'soft'),isLocked()?'disabled':'')+'<p class="hint">列表中的全部可用资料将参与分析</p></div><div class="workset-list">'+(manage?'<div class="row wrap" style="padding:5px">'+A('全选','manage-all')+A('移出 '+manageIds.length+' 份','manage-remove')+'</div>':'')+(docs.length?folders.map(f=>'<button class="work-folder" data-action="folder-manage" data-id="'+E(f)+'">'+I('folder','icon-sm')+E(f)+I('chevron','icon-sm')+'</button>'+docs.filter(d=>d.folder===f).map(d=>'<div class="work-file '+(w.preview===d.id?'active':'')+'">'+(manage?'<input type="checkbox" aria-label="勾选移出 '+E(d.name)+'" data-change="manage-check" data-id="'+d.id+'" '+(manageIds.includes(d.id)?'checked':'')+'>':ficon(d))+'<button class="filename" data-action="preview" data-id="'+d.id+'">'+E(d.name)+'<div class="file-sub">'+(d.local?'待解析':'可分析')+'</div></button>'+(!isLocked()&&!manage?'<button class="iconbtn" title="移出本次分析，原文件保留" aria-label="移出 '+E(d.name)+'" data-action="remove-file" data-id="'+d.id+'">'+I('close','icon-sm')+'</button>':'')+'</div>').join('')).join(''):'<div class="file-placeholder">还没有添加资料<br>从资料库选择文件，或从资料库添加资料。</div>')+(!ids.length?B('载入资料','sample','soft w100'):'')+'</div>'+runbox()+'</aside>';}
function runbox(){const t=tool(state.toolId),w=ws(),task=currentTask();if(task){return '<div class="runbox"><p>'+E(task.status==='running'?'任务运行中，可在任务中心查看':task.status==='awaiting'?'下一步：填写计费基数':task.status==='partial'?'成功结果已保留，可重试失败文件':'本次配置与资料已保存为任务快照')+'</p>'+B(task.status==='running'?I('pause')+'停止任务':task.status==='awaiting'?I('arrow')+'填写基数':I('plus')+'复制配置新建',task.status==='running'?'stop-task':task.status==='awaiting'?'focus-base':'new-analysis',task.status==='running'?'':'primary')+'</div>';}let errors=validate(false);return '<div class="runbox"><p>'+ (errors.length?E(errors[0]):'已就绪 · '+w.ids.length+' 份资料'+(w.config.merge&&['extract','contract'].includes(t.id)?'，含关联附件':''))+'</p>'+B(I('play')+(t.id==='prepaid'?'提取计费约定':'执行分析'),'run','primary',!w.ids.length&&t.id!=='bidding'?'disabled':'')+'<p style="margin:9px 0 0;text-align:center">执行 · 不发送到后台</p></div>';}
function preparation(){const w=ws(),t=tool(state.toolId);const meetingTabs=t.id==='meeting'?'<div class="panel-tabs card mb"><div class="tabs">'+[['regular','常规分析'],['risk','风险分析'],['qa','深度问答']].map(([v,n])=>'<button class="tab '+(w.subtab===v?'active':'')+'" data-action="meeting-tab" data-id="'+v+'">'+n+'</button>').join('')+'</div></div>':'';if(t.id==='meeting'&&w.subtab!=='regular')return meetingTabs+'<div class="card">'+empty('先完成常规分析','会议风险报告与深度问答基于同一批会议与议题结果。添加纪要，完成一次常规分析即可继续。','去常规分析','meeting-base','message')+'</div>';return meetingTabs+'<div class="card preview"><div class="panel-tabs"><div class="tabs"><span class="tab active">资料预览</span></div>'+tag(w.preview?'原文':'准备分析','blue')+'</div>'+(w.preview?documentPreview(w.preview):empty('先添加资料，再开始分析','选择需要分析的文件，右侧确认'+(t.id==='word'?'用词设置':'分析内容')+'。完成后，'+t.output+'将显示在这里。','载入'+(t.id==='meeting'?'会议':'')+'资料','sample',t.icon))+'</div><div class="initial-help">'+I('help')+'<span>点击左侧文件名只切换预览，不改变分析范围。所有分析结果均可从任务中心找回。</span></div>';}
function documentPreview(id,highlight=false){const d=file(id);if(!d)return empty('资料不可用','该资料可能已被移除。');if(d.local)return '<div class="docstage">'+empty('文件尚未解析','文件正在等待解析，完成后可查看原文。',null,null,'file')+'</div>';if(d.rows)return '<div class="cardbody"><div class="notice">'+I('help')+'<span>当前表格共 '+d.rows.length+' 行。</span></div><h3 class="mt mb">'+E(d.name)+'</h3>'+simpleTable(d.columns,d.rows)+'</div>';return '<div class="docstage"><article class="document"><div class="doc-kicker">AUDIT DOCUMENT / 原文</div><h2>'+E(d.title)+'</h2><div class="doc-meta">'+E(d.unit)+'　｜　'+E(d.date)+'</div>'+(d.text||'').split('\n').map((p,i)=>'<p>'+(highlight&&i===1?'<mark>'+E(p)+'</mark>':E(p))+'</p>').join('')+'<div class="doc-end">全文 · '+E(d.name)+'</div></article></div>';}
function options(values,current){return values.map(v=>'<option '+(v===current?'selected':'')+' value="'+E(v)+'">'+E(v)+'</option>').join('');}
function selectConfig(key,values,disabled=false){return '<select data-config="'+key+'" '+(disabled?'disabled':'')+'>'+options(values,currentConfig()[key])+'</select>';}
function configPanel(){const t=tool(state.toolId),w=ws(),c=currentConfig(),locked=isLocked();let html='<aside class="config"><div class="row between"><h3>'+(locked?'本次配置':'分析设置')+'</h3>'+tag(locked?'任务快照':'默认已配置',locked?'':'blue')+'</div>';if(locked)html+='<p class="hint">修改配置请复制新建，原任务结果保持不变。</p>';if(t.id==='meeting'&&w.subtab==='qa')return html+'<div class="notice mt">'+I('message')+'<span>问答仅基于本次已分析纪要。每条回答分别保留来源，不会重新运行基础分析。</span></div><div class="field"><label>相关资料</label>'+selectedDocs(currentTask()?.ids||w.ids).map(d=>sourceLink(d.id)).join('')+'</div></aside>';
if(t.id==='contract')html+='<div class="field"><label>合同类型</label>'+selectConfig('contractType',['采购合同','施工合同','服务合同'],locked)+'</div>';
if(t.id==='contract')html+='<div class="field"><label>基础信息提取模板</label>'+selectConfig('contractDataTemplate',['合同基础信息提取'],locked)+'<div class="hint">合同主体、金额、关键日期与类型。</div></div>';
if(t.id==='prepaid')html+='<div class="field"><label>费用类型</label>'+selectConfig('feeType',['工程监理服务费'],locked)+'<div class="hint">提供监理计费约定；正式类型来自现有后台配置。</div></div>';
if(t.id==='bidding')html+='<div class="field"><label>分析内容</label>'+[['tender','招标文件分析','检查资格条件、评分与需求表述'],['bid','投标文件分析','检查各单位响应与材料完整性'],['joint','招投标联合分析','对照同一项目的招标与投标资料']].map(([id,n,d])=>'<div class="mode-card"><label><input type="checkbox" data-change="bid-mode" value="'+id+'" '+((currentTask()?.modes||w.modes).includes(id)?'checked':'')+' '+(locked?'disabled':'')+'>'+n+'</label><small>'+d+'</small></div>').join('')+'</div>';
if(t.id==='bidding')html+=(currentTask()?.modes||w.modes).map(m=>'<div class="field"><label>'+({tender:'招标分析模板',bid:'投标分析模板',joint:'联合分析模板'}[m])+'</label>'+selectConfig({tender:'bidTenderTemplate',bid:'bidBidTemplate',joint:'bidJointTemplate'}[m],[{tender:'招标条件与评分检查',bid:'投标响应完整性检查',joint:'招投标联合对照检查'}[m]],locked)+'</div>').join('');
if(t.id!=='word'){html+='<div class="field"><label>'+(t.id==='theme'?'1. 基础信息提取模板':t.id==='engineering'?'重复项目分析模板':'分析模板')+'</label><select data-config="template" '+(locked?'disabled':'')+'>'+options([...new Set([t.template,...state.templates.filter(p=>p.toolId===t.id).map(p=>p.name),c.template])],c.template)+'</select><div class="hint">系统模板 · '+t.output+'</div></div>';
if(t.id==='theme'||t.id==='engineering')html+='<div class="field"><label>'+(t.id==='theme'?'2. 主题归纳模板':'主子项目分析模板')+'</label><select data-config="secondTemplate" '+(locked?'disabled':'')+'>'+options(t.id==='theme'?['审计事项共同主题归纳']:['主子项目关系识别'],c.secondTemplate)+'</select><div class="hint">'+(t.id==='theme'?'一次执行，依次完成两步。':'两类分析同时执行，结果分开查看。')+'</div></div>';
}
if(t.id==='extract')html+='<div class="field"><div class="row between"><label class="no-margin">提取内容 · '+c.fields.length+' 项</label>'+A(locked?'查看字段':'调整字段','edit-fields')+'</div>'+c.fields.map((f,i)=>'<div class="rule-row"><span class="number-label">'+(i+1)+'</span>'+E(f)+'</div>').join('')+'</div>';
if(t.id==='risk'||t.id==='contract')html+='<div class="field"><div class="row between"><label class="no-margin">'+(t.id==='risk'?'本次关注点':'检查规则')+' · '+c.checks.length+' 项</label>'+(!locked?A('全选','check-all'):'')+'</div>'+(t.checks||[]).map(f=>'<div class="rule-row"><label><input type="checkbox" data-change="risk-check" value="'+f+'" '+(c.checks.includes(f)?'checked':'')+' '+(locked?'disabled':'')+'>'+f+'</label></div>').join('')+(t.id==='risk'?'<div class="field"><label>分析方式</label><select data-config="mode" '+(locked?'disabled':'')+'>'+options(['逐文件检查全部关注点','逐关注点检查各文件'],c.mode)+'</select><p class="hint">两种方式均为逐份分析，不进行跨文档综合判断。</p></div>':'')+'</div>';
if(t.id==='word')html+='<div class="field"><label>展示词数</label><input type="number" min="10" max="500" data-config="top" value="'+c.top+'" '+(locked?'disabled':'')+'><p class="hint">展示前 10–500 个高频词；不限制分析范围。</p></div><div class="field"><label>用词设置</label>'+B(I('settings')+'管理我的词库','lexicon','w100')+'<div class="hint">停用词 '+state.stopwords.length+' 个 · 专有词 '+state.newwords.length+' 个</div></div><div class="notice mt">'+I('help')+'<span>词频表示出现次数，不代表风险程度。词库改动在下次执行时生效。</span></div>';
if(t.id==='engineering')html+='<div class="field"><label>资料与字段对应</label>'+selectedDocs(currentTask()?.ids||w.ids).map(d=>'<p class="hint">'+E(d.name)+' '+tag(d.rows?'表头可用':'需表格','blue')+'</p>').join('')+mappingFields(false,locked)+'</div>';
if(['extract','contract'].includes(t.id))html+='<div class="field"><label class="row-radio"><input type="checkbox" data-config="merge" '+(c.merge?'checked':'')+' '+(locked?'disabled':'')+'>将关联附件与主文件合并分析</label><div class="hint">本次 '+(selectedDocs(currentTask()?.ids||w.ids).reduce((n,d)=>n+raAttachmentIds(d).length,0))+' 份关联附件。'+A('管理附件','attachments')+'</div></div>';
if(t.id!=='word')html+='<div class="field">'+B(I('book')+(locked?'查看分析要求':'查看 / 调整分析要求'),'prompt','w100')+(!locked?'<div class="row between mt"><span class="hint">系统模板原件保持只读</span>'+A('另存我的模板','save-template')+'</div>':'')+'</div>';
html+='<details><summary>高级设置</summary>'+(t.id==='meeting'?'<div class="field"><label>议题归类相似度阈值</label><input type="number" min="0" max="1" step=".05" data-config="cluster" value="'+(c.cluster||.8)+'" '+(locked?'disabled':'')+'><div class="hint">用于归并相近议题，不是结果准确率。</div></div>':'')+(t.id==='engineering'?'<div class="field"><label>判定阈值（0–5分）</label><input type="number" min="0" max="5" step=".1" data-config="threshold" value="'+c.threshold+'" '+(locked?'disabled':'')+'></div>':'')+'<div class="field"><label>文本切片长度（字符）</label><input type="number" min="100" max="20000" data-config="chunk" value="'+c.chunk+'" '+(locked?'disabled':'')+'></div><div class="field"><label>重叠长度（字符）</label><input type="number" min="0" data-config="overlap" value="'+c.overlap+'" '+(locked?'disabled':'')+'></div><div class="field"><label>状态</label><select data-config="failure" '+(locked?'disabled':'')+'>'+[['none','正常完成'],['partial','部分文件失败'],['fail','本次执行失败']].map(([v,n])=>'<option value="'+v+'" '+(c.failure===v?'selected':'')+'>'+n+'</option>').join('')+'</select><div class="hint">仅用于评审异常恢复交互。</div></div></details></aside>';return html;}
function mappingFields(two=false,locked=false){const c=currentConfig(),w=ws();const a=file(two?w.tableA:(currentTask()?.ids||w.ids)[0]),b=file(w.tableB);let rows=[['项目名称','mapName',a?.columns||['项目名称']],['建设 / 实施单位','mapUnit',a?.columns||['建设单位']],['投资金额（万元）','mapAmount',a?.columns||['计划投资（万元）']]];if(two)return simpleTable(['比较内容',E(w.tableAName),E(w.tableBName)],rows.map(([label,key,cols],i)=>[label,'<select aria-label="表一'+label+'" data-config="'+key+'" '+(locked?'disabled':'')+'>'+options(['请选择',...cols],c[key])+'</select>','<select aria-label="表二'+label+'" data-config="'+['mapBName','mapBUnit','mapBAmount'][i]+'" '+(locked?'disabled':'')+'>'+options(['请选择',...(b?.columns||['项目名称','实施单位','安排资金（万元）'])],c[['mapBName','mapBUnit','mapBAmount'][i]])+'</select>']),true,'mapping');
return rows.map(([label,key,cols])=>'<div class="field"><label>'+label+'</label><select data-config="'+key+'" '+(locked?'disabled':'')+'>'+options(['请选择',...cols],c[key])+'</select></div>').join('');}
function simpleTable(headers,rows,raw=false,cls=''){return '<div class="tablewrap"><table class="table '+cls+'"><thead><tr>'+headers.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(x=>'<td>'+(raw?x:E(x))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';}
function sourceLink(id,label){const d=file(id);return d?'<button class="source-link" data-action="source" data-id="'+id+'">'+I('file')+E(label||d.name)+I('chevron','icon-sm')+'</button>':'';}
function associationSidebar(){const w=ws(),locked=isLocked();return '<aside class="workset"><div class="workset-top"><h3>比较资料</h3><p class="hint">分别指定两张表，来源名称可以修改。</p>'+[['A','待查项目表'],['B','对照项目表']].map(([s,n])=>'<div class="slot-large">'+tag('表'+(s==='A'?'一':'二'),'blue')+'<input class="w100" style="font-size:16px" aria-label="表'+s+'业务名称" data-work="table'+s+'Name" value="'+E(w['table'+s+'Name'])+'" '+(locked?'disabled':'')+'>'+(w['table'+s]?'<p>'+E(file(w['table'+s])?.name)+'</p><div class="row">'+B('更换','pick-table','sm','data-slot="'+s+'" '+(locked?'disabled':''))+A('移出','remove-table','data-slot="'+s+'" '+(locked?'disabled':''))+'</div>':'<p>请选择可分析的项目台账</p>'+B(I('plus')+'添加表'+(s==='A'?'一':'二'),'pick-table','sm soft','data-slot="'+s+'"'))+'</div>').join('')+(!w.tableA&&!w.tableB?B('载入两表','sample','soft w100 mt'):'')+'<div class="hint mt">大表不加载整表预览。核验时查看结果对应的来源行与字段。</div></div><div class="grow"></div>'+runbox()+'</aside>';}
function associationPreparation(){const c=currentConfig();return '<div class="card"><div class="cardhead"><div><h3>对应两张表的比较字段</h3><p class="hint">先确认“比较什么”，评分细节放在高级设置。</p></div>'+tag('第 2 步','blue')+'</div><div class="cardbody"><div class="field no-margin"><label>比较模板</label>'+selectConfig('template',[tool('association').template,...state.templates.filter(t=>t.toolId==='association').map(t=>t.name)])+'</div><div class="mt">'+mappingFields(true)+'</div><div class="notice mt">'+I('help')+'<span>金额字段单位均为万元。字段名称必须存在于对应表头中；不自动进行单位换算。</span></div><details open><summary>比较规则与执行模式</summary><div class="form-grid mt"><div class="field"><label>执行模式</label><select data-config="matchMode">'+[['standard','标准模式 · 完整候选比较'],['batch','批量模式 · 保留前 N 个候选']].map(([v,n])=>'<option value="'+v+'" '+(c.matchMode===v?'selected':'')+'>'+n+'</option>').join('')+'</select></div><div class="field"><label>批量候选上限 N</label><input type="number" min="1" max="1000" data-config="cap" value="'+c.cap+'" '+(c.matchMode==='standard'?'disabled':'')+'></div></div><p class="hint">批量模式会截断候选范围；不能把未返回记录解释为无关联。</p><div class="form-grid mt"><div class="field"><label>判定阈值（0–5 分）</label><input type="number" min="0" max="5" step=".1" data-config="threshold" value="'+c.threshold+'"></div><div class="field"><label>项目名称权重（0–1）</label><input type="number" min="0" max="1" step=".1" data-config="weightName" value="'+c.weightName+'"><p class="hint">单位权重自动补足为 1 − 名称权重。</p></div></div></details><details><summary>字段评分与候选保留策略</summary>'+simpleTable(['比较内容','评分方式','权重','阈值（0–5）'],(c.compareRules||[]).map((r,i)=>[E(r.name),'<select aria-label="'+E(r.name)+'评分方式" data-rule="'+i+':type">'+options(['文本相似','精确匹配','数值比较'],r.type)+'</select>','<input aria-label="'+E(r.name)+'权重" type="number" min="0" max="1" step=".1" style="width:76px" data-rule="'+i+':weight" value="'+r.weight+'">','<input aria-label="'+E(r.name)+'阈值" type="number" min="0" max="5" step=".1" style="width:76px" data-rule="'+i+':threshold" value="'+r.threshold+'">']),true)+'<div class="form-grid mt"><div class="field"><label>完全关联阈值（0–5分）</label><input data-config="perfectThreshold" type="number" min="0" max="5" step=".1" value="'+(c.perfectThreshold||5)+'"></div><div class="field"><label>候选保留策略</label><select data-config="lockStrategy">'+options(['保留全部候选','锁定最佳候选'],c.lockStrategy||'保留全部候选')+'</select></div></div><p class="hint">详细规则保留在任务快照，候选关系应结合原文进一步核验。</p></details><details><summary>分析要求与状态</summary><div class="field"><label>分析要求</label><textarea data-config="prompt">'+E(c.prompt)+'</textarea></div><div class="field"><label>执行状态</label><select data-config="failure">'+[['none','正常完成'],['partial','部分失败'],['fail','执行失败']].map(([v,n])=>'<option value="'+v+'" '+(c.failure===v?'selected':'')+'>'+n+'</option>').join('')+'</select></div></details><div class="row between mt"><span class="hint">输出关联候选及原因，需进一步核验。</span>'+B(I('book')+'另存模板','save-template')+'</div></div></div>';}
function biddingPreparation(){const w=ws();const pending=(w.unassigned||[]).length?'<div class="card mb"><div class="cardhead"><h3>待归组资料 · '+w.unassigned.length+' 份</h3>'+tag('请指定角色','amber')+'</div><div class="cardbody">'+w.unassigned.map(id=>'<div class="slot-file"><span>'+E(file(id)?.name)+'</span>'+B('指定项目与角色','assign-bid','sm','data-id="'+id+'"')+'</div>').join('')+'</div></div>':'';return pending+'<div class="notice">'+I('help')+'<span>请明确文件所属项目及角色。系统不会仅凭文件名自动认定招标或投标单位。</span></div>'+w.projects.map((p,pi)=>'<section class="project-card"><div class="project-head"><span class="number-label">'+(pi+1)+'</span><input aria-label="项目名称" data-project="'+p.id+'" value="'+E(p.name)+'">'+(w.projects.length>1?'<button class="iconbtn" aria-label="移除项目 '+E(p.name)+'" data-action="remove-project" data-id="'+p.id+'">'+I('close')+'</button>':'')+'</div><div class="cardbody"><div class="drop-slot"><div class="row between"><h4>招标资料</h4>'+B(I('plus','icon-sm')+'添加招标文件','pick-bid','sm','data-project="'+p.id+'" data-role="tender"')+'</div>'+p.tender.map(id=>bidFile(id,p.id,'tender')).join('')+(!p.tender.length?'<p class="hint">招标文件、采购需求及补充说明</p>':'')+'</div><div class="row between mt"><h4>投标单位</h4>'+A('＋ 新增单位','add-bidder','data-id="'+p.id+'"')+'</div>'+p.bidders.map((b,bi)=>'<div class="bidder"><div class="row"><input aria-label="投标单位名称" data-bidder="'+p.id+':'+bi+'" value="'+E(b.name)+'" style="font-size:16px;width:100%"><button class="iconbtn" data-action="remove-bidder" data-project="'+p.id+'" data-index="'+bi+'" aria-label="移除投标单位">'+I('close','icon-sm')+'</button></div>'+b.files.map(id=>bidFile(id,p.id,'bid',bi)).join('')+B(I('plus','icon-sm')+'添加该单位投标文件','pick-bid','sm ghost mt','data-project="'+p.id+'" data-role="bid" data-index="'+bi+'"')+'</div>').join('')+'</div></section>').join('')+B(I('plus')+'新增项目','add-project','w100')+(!w.ids.length?B('载入一个项目与两家单位的','sample','soft w100 mt'):'');}
function bidFile(id,project,role,index){return '<div class="slot-file"><button class="link" data-action="source" data-id="'+id+'">'+E(file(id)?.name)+'</button><button class="iconbtn" aria-label="移出此资料关联" data-action="remove-bidfile" data-id="'+id+'" data-project="'+project+'" data-role="'+role+'" data-index="'+(index??'')+'">'+I('close','icon-sm')+'</button></div>';}
function validate(show=true){const w=ws(),c=w.config,t=tool(state.toolId),errs=[];if(!w.ids.length)errs.push('请先添加需要分析的资料');if(w.ids.some(id=>file(id)?.local))errs.push('所选文件尚未完成解析，请稍后重试');if(!c.template)errs.push('请选择分析模板');if(t.id==='extract'&&(!c.fields.length||c.fields.some(f=>!f.trim())||new Set(c.fields).size!==c.fields.length))errs.push('请填写不重复的提取字段');if(['risk','contract'].includes(t.id)&&!c.checks.length)errs.push('请至少选择一个关注点或检查规则');if(t.id==='word'&&(+c.top<10||+c.top>500))errs.push('展示词数需在 10–500 之间');
if(t.id==='engineering'){selectedDocs(w.ids).forEach(d=>{if(!d.rows)errs.push(d.name+' 需要台账表格');else if([c.mapName,c.mapUnit,c.mapAmount].some(f=>!d.columns.includes(f)))errs.push(d.name+' 的字段对应不完整');});}
if(t.id==='association'){if(!w.tableA||!w.tableB)errs.push('请分别添加表一和表二');if(w.tableA===w.tableB&&w.tableA)errs.push('本请使用两份不同台账');for(const [id,keys] of [[w.tableA,['mapName','mapUnit','mapAmount']],[w.tableB,['mapBName','mapBUnit','mapBAmount']]]){const d=file(id);if(d&&(!d.rows||keys.some(k=>!d.columns.includes(c[k]))))errs.push('请完成两张表的有效字段对应');}if(+c.threshold<0||+c.threshold>5)errs.push('判定阈值需在 0–5 分之间');if(c.compareRules?.some(r=>!Number.isFinite(+r.weight)||+r.weight<0||+r.weight>1||+r.threshold<0||+r.threshold>5))errs.push('请检查每个字段的权重和阈值');if(c.compareRules&&Math.abs(c.compareRules.reduce((n,r)=>n+(+r.weight),0)-1)>0.001)errs.push('各字段权重之和需为1');if(+c.perfectThreshold<+c.threshold||+c.perfectThreshold>5)errs.push('完全关联阈值须不小于候选阈值且不大于5');if(+c.weightName<0||+c.weightName>1)errs.push('名称权重需在 0–1 之间');if(c.matchMode==='batch'&&(!Number.isInteger(+c.cap)||+c.cap<1||+c.cap>1000))errs.push('候选上限须为 1–1000 的整数');}
if(t.id==='bidding'){if(w.unassigned?.length)errs.push('请先为 '+w.unassigned.length+' 份资料指定项目与文件角色');if(!w.modes.length)errs.push('请至少选择一种分析内容');w.projects.forEach(p=>{if(!p.name.trim())errs.push('请填写项目名称');if((w.modes.includes('tender')||w.modes.includes('joint'))&&!p.tender.length)errs.push(p.name+'：请添加招标文件');if((w.modes.includes('bid')||w.modes.includes('joint'))&&!p.bidders.some(b=>b.files.length))errs.push(p.name+'：请添加至少一家单位的投标文件');if(p.bidders.some(b=>b.files.length&&!b.name.trim()))errs.push(p.name+'：请填写投标单位名称');});}
if(+c.chunk<100||+c.overlap<0||+c.overlap>=+c.chunk)errs.push('切片长度至少为100，重叠长度须小于切片长度');if(show&&errs.length)openModal('validation',{errors:errs});return errs;}
function makeResult(task){const ds=selectedDocs(task.successIds||task.ids),c=task.config;const base=ds.map(d=>({doc:d.id,title:d.title||d.name,unit:d.unit||'未提取到',amount:d.amount||'未提取到',date:d.date,topic:d.topic||'资料整理',excerpt:(d.text||'').split('\n')[1]||d.text||'台账记录'}));switch(task.toolId){
case 'extract':return base.map(d=>({...d,values:c.fields.map(f=>f.includes('单位')||f.includes('主体')?d.unit:f.includes('金额')?d.amount:f.includes('日期')||f.includes('时间')?d.date:f.includes('主题')||f.includes('名称')?d.title:'未提取到')}));
case 'word':{let txt=ds.map(d=>d.text||JSON.stringify(d.rows)).join('\n');return [...new Set([...WORDS.map(x=>x[0]),...(task.newwords||[])])].filter(w=>!(task.stopwords||[]).includes(w)).map(w=>({word:w,count:txt.split(w).length-1,docs:ds.filter(d=>(d.text||JSON.stringify(d.rows)).includes(w)).map(d=>d.id)})).filter(x=>x.count>0).sort((a,b)=>b.count-a.count);}
case 'risk':return base.flatMap(d=>c.checks.map((check,i)=>({...d,check,judgment:i===0?'待核验':'资料线索',detail:check==='决策程序'?'请核对相关审批材料与决策记录是否齐备。':check==='预算执行'?'请对照批准预算与后续执行材料；本条仅摘录当前文件。':check==='合同履约'?'请核对原文约定与实际履约凭证。':'请核对原文涉及的附件、记录是否完整。'})));
case 'contract':return base.flatMap(d=>c.checks.map((check,i)=>({...d,check,judgment:i===2?'需关注':'已提取',detail:i===2?'正文引用了技术附件，需结合附件核实具体验收标准。':'请结合原文及本次检查要求复核，不自动认定为合规结论。'})));
case 'meeting':return ds.flatMap(d=>(d.text||'').split('\n').filter(p=>p.startsWith('议题')).map((p,i)=>({...base.find(r=>r.doc===d.id),topic:/设备采购/.test(p)?'设备采购':/园区改造/.test(p)?'园区改造':/验收/.test(p)?'设备验收':/付款/.test(p)?'工程付款':d.topic,excerpt:p,amount:p.match(/(\d+(?:\.\d+)?)万元/)?.[1]+' 万元',participants:(d.text||'').match(/参会：([^。]+)/)?.[1]||'未提取到',agenda:i+1}))).map(r=>({...r,amount:r.amount==='undefined 万元'?'未提取到':r.amount}));
case 'bidding':return task.projects.flatMap(p=>task.modes.flatMap(mode=>{const docs=mode==='tender'?p.tender:p.bidders.flatMap(b=>b.files);return docs.filter(id=>task.successIds.includes(id)).map((id,i)=>({doc:id,title:p.name,unit:p.bidders.find(b=>b.files.includes(id))?.name||'招标方',check:mode==='tender'?'资格条件与评分':mode==='bid'?'投标响应完整性':'招投标响应对照',judgment:mode==='joint'&&p.bidders.filter(b=>b.files.length).length<2?'部分检查不适用':'待核验',detail:mode==='joint'&&p.bidders.filter(b=>b.files.length).length<2?'仅一家投标单位，不能进行单位间比较。':'请按所选规则对照来源资料；此条是交互结果。',excerpt:file(id)?.text?.split('\n')[1]||'',refs:[...p.tender,id].filter((x,i,a)=>a.indexOf(x)===i)}));}));
case 'engineering':return ds.filter(d=>d.rows).flatMap(d=>[{doc:d.id,kind:'duplicate',a:d.rows[0]?.[0],b:d.rows[1]?.[0],score:4.5,detail:'名称表述相近、建设单位和投资金额一致，形成疑似重复候选；需核对项目编码与立项依据。',rows:[d.rows[0],d.rows[1]]},{doc:d.id,kind:'parent',a:d.rows[0]?.[0],b:d.rows[2]?.[0],score:4.1,detail:'设备购置可能为园区改造的配套事项，属于主子关系候选，需核对项目范围。',rows:[d.rows[0],d.rows[2]]}]).filter(r=>r.score>=+c.threshold);
case 'association':{const a=file(task.tableA),b=file(task.tableB);return (a?.rows||[]).slice(0,Math.min(b?.rows.length||0,c.matchMode==='batch'?+c.cap:999)).map((r,i)=>({doc:a.id,other:b.id,a:r,b:b.rows[i],score:i===0?5:i===1?4.2:3.7,detail:i===0?'项目名称和单位相同，作为关联候选。':'名称或资金用途存在关联，需结合立项材料确认，不能仅凭分数认定。'})).filter(r=>r.score>=+c.threshold);}
default:return base;
}}
function run(retryTask){if(!retryTask&&validate().length)return;const w=ws();let task;if(retryTask){task=retryTask;task.status='running';task.progress=0;task.phase='正在重试失败文件';task.retryCount=(task.retryCount||0)+1;}else{task={id:'T'+Date.now(),name:tool(state.toolId).name+' · '+new Date().toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}),toolId:state.toolId,ids:[...w.ids],config:structuredClone(w.config),projects:structuredClone(w.projects),modes:[...w.modes],tableA:w.tableA,tableB:w.tableB,tableAName:w.tableAName,tableBName:w.tableBName,status:'running',progress:0,created:new Date().toISOString(),phase:'正在准备资料',attachments:structuredClone(Object.fromEntries(selectedDocs(w.ids).map(d=>[d.id,raAttachmentIds(d,null)]))),stopwords:[...state.stopwords],newwords:[...state.newwords],chats:[],report:false,meetingRisk:false,substage:null};state.tasks.unshift(task);w.taskId=task.id;}task.startedAt=new Date().toISOString();task.lastProgressAt=task.startedAt;delete task.completed;delete task.finishedAt;configExpanded=false;w.tab='result';persist();render();let tick=0;clearInterval(runTimers[task.id]);runTimers[task.id]=setInterval(()=>{if(task.status!=='running'){clearInterval(runTimers[task.id]);return;}tick++;task.lastProgressAt=new Date().toISOString();task.progress=Math.min(96,tick*16);task.phase=tick<2?'正在读取资料':tick<4?(task.toolId==='theme'?'正在提取基础信息':task.toolId==='meeting'?'正在归并会议与议题':'正在按本次配置分析'):(task.toolId==='theme'?'正在归纳共同主题':'正在整理结果与来源');if(tick>=6){clearInterval(runTimers[task.id]);task.completed=task.lastProgressAt;task.progress=100;task.failedIds=!task.retryCount&&task.config.failure==='fail'?[...task.ids]:!task.retryCount&&task.config.failure==='partial'?[task.ids[task.ids.length-1]]:[];task.successIds=task.ids.filter(id=>!task.failedIds.includes(id));task.status=task.failedIds.length?(task.successIds.length?'partial':'failed'):task.toolId==='prepaid'?'awaiting':'completed';task.phase=task.status==='awaiting'?'待填写计费基数':task.status==='completed'?'分析完成':task.status==='partial'?'部分文件分析失败':'分析失败';task.result=makeResult(task);persist();toast(task.status==='completed'?'分析完成，结果已保存到任务中心':task.phase);}
if(state.view==='tool'&&currentTask()?.id===task.id||state.view==='tasks')render();},450);}
function taskArea(task){const w=ws(),t=tool(task.toolId);if(task.status==='running')return '<div class="card"><div class="progress-shell"><div class="progress-icon">'+I(t.icon)+'</div><h2>'+E(task.phase)+'</h2><p class="hint">处理中 · '+task.ids.length+' 份资料 · '+E(task.config.template)+'</p><div class="progress-track"><i style="width:'+task.progress+'%"></i></div><div class="row between small muted"><span>处理进度</span><span>'+task.progress+'%</span></div><div class="log"><div>'+I('check','icon-sm')+'本次资料与配置已保存为任务快照</div><div>'+I('clock','icon-sm')+'可离开此页，在任务中心继续查看</div><div>'+I('file','icon-sm')+'已建立处理任务</div></div>'+B('前往任务中心','nav-tasks','mt')+'</div></div>';
if(['failed','stopped'].includes(task.status))return '<div class="card">'+empty(task.status==='failed'?'本次分析未完成':'任务已停止',task.status==='failed'?'已保留资料与配置。此处服务失败，可直接重试；不会删除源资料。':'成功停止本地计时器。资料与配置仍可复制继续。','重试本次分析','retry-task','refresh')+'</div>';
let header='<div class="result-summary"><span class="success-ring">'+I(task.status==='awaiting'?'clock':'check')+'</span><div><h3>'+(task.status==='awaiting'?'计费约定已提取':task.status==='partial'?'部分结果已生成':'分析结果已生成')+'</h3><p>'+(task.successIds?.length||0)+' 份资料 · '+E(task.config.template)+'</p></div><div class="result-actions">'+B(I('settings')+'本次配置','toggle-config','sm')+B(I('expand'),'full-result','sm','aria-label="切换结果宽屏"')+B(I('download')+'导出','export','sm')+'</div></div>';
if(task.status==='partial')header+='<div class="notice amber mb">'+I('help')+'<span class="grow">'+task.failedIds.length+' 份资料失败，已保留成功结果。'+task.failedIds.map(id=>E(file(id)?.name)).join('、')+'</span>'+A('重试失败','retry-task')+'</div>';
if(task.toolId==='meeting')header+='<div class="panel-tabs card mb"><div class="tabs">'+[['regular','常规分析'],['risk','风险分析'],['qa','深度问答']].map(([id,n])=>'<button class="tab '+(w.subtab===id?'active':'')+'" data-action="meeting-tab" data-id="'+id+'">'+n+'</button>').join('')+'</div>'+tag('基于本次常规分析','blue')+'</div>';
if(w.tab==='preview')return header+'<div class="card"><div class="panel-tabs"><div class="tabs"><button class="tab" data-action="show-result">分析结果</button><span class="tab active">原文预览</span></div>'+A('返回结果','show-result')+'</div>'+documentPreview(w.preview)+'</div>';
return header+resultContent(task);}
function resultToolbar(task,extra=''){return '<div class="result-tools"><div class="search">'+I('search')+'<input aria-label="筛选结果" placeholder="筛选当前结果，不重新分析" value="'+E(resultFilter)+'" data-input="result-filter"></div><div class="row"><select aria-label="结果文件范围" class="result-filefilter" data-change="result-scope"><option value="all">任务全部资料</option>'+task.successIds.map(id=>'<option value="'+id+'" '+(resultScope===id?'selected':'')+'>'+E(file(id)?.name)+'</option>').join('')+'</select>'+extra+'</div></div>';}
function filterResults(rows){return rows.filter(r=>(resultScope==='all'||r.doc===resultScope)&&JSON.stringify(r).toLowerCase().includes(resultFilter.toLowerCase()));}
function noResult(){return '<div class="empty" style="min-height:220px"><div class="empty-icon">'+I('search')+'</div><h3>当前筛选没有匹配结果</h3><p>清除筛选即可查看本次任务全部结果，无需重新分析。</p>'+B('清除筛选','clear-result')+'</div>';}
function resultContent(task){const id=task.toolId,w=ws(),rows=filterResults(task.result||[]);
if(id==='extract')return '<div class="card result-card">'+resultToolbar(task)+ (rows.length?simpleTable(['来源文件',...task.config.fields,'核验'],rows.map(r=>[E(file(r.doc)?.name),...r.values.map(E),sourceLink(r.doc,'查看原文')]),true):noResult())+'<div class="scroll-hint">“未提取到”表示本次结果没有该值，不自动认定原文未提及。导出保留完整内容。</div></div>';
if(id==='word'){const all=(task.result||[]).filter(r=>r.word.includes(resultFilter)&&(resultScope==='all'||r.docs.includes(resultScope))),words=all.slice(0,task.displayTop||task.config.top),max=words[0]?.count||1;return '<div class="card">'+resultToolbar(task,'<input style="width:70px" type="number" min="10" max="500" aria-label="展示词数" data-change="display-top" value="'+(task.displayTop||task.config.top)+'">')+'<div class="notice" style="border-radius:0;border-width:0 0 1px">'+I('help')+'<span>高频仅表示出现次数，不代表风险。展示 '+words.length+' 个词；点击词语查看本次资料中的来源。</span></div>'+(words.length?'<div class="grid2" style="gap:0"><div class="cloud">'+words.map((r,i)=>'<button data-action="word-detail" data-word="'+E(r.word)+'" style="font-size:'+(16+Math.round(r.count/max*25))+'px;color:'+['#487db9','#75a49d','#7897c4','#496781'][i%4]+'">'+E(r.word)+'</button>').join('')+'</div><div>'+simpleTable(['词语','出现次数','查看'],words.map(r=>[E(r.word),'<span class="score">'+r.count+'</span><div class="bar"><i style="width:'+r.count/max*100+'%"></i></div>',A('来源','word-detail','data-word="'+E(r.word)+'"')]),true)+'</div></div>':noResult())+'</div>';}
if(id==='theme')return '<div class="card"><div class="panel-tabs"><div class="tabs">'+[['main','主题归纳'],['base','基础信息表']].map(([v,n])=>'<button class="tab '+(w.subtab===v?'active':'')+'" data-action="subtab" data-id="'+v+'">'+n+'</button>').join('')+'</div>'+tag('两阶段已完成','green')+'</div>'+(w.subtab==='base'?resultToolbar(task)+simpleTable(['文档','涉及单位','金额','日期','来源'],rows.map(r=>[E(r.title),E(r.unit),E(r.amount),E(r.date),sourceLink(r.doc,'查看原文')]),true):'<div class="cardbody reading"><div class="eyebrow">THEMATIC SUMMARY</div><h2>本批资料主要事项归纳</h2><p class="muted small">基于 '+task.successIds.length+' 份资料 · 提取基础信息 → 归纳共同主题</p>'+[...new Set(task.result.map(r=>r.topic))].map((topic,i)=>'<h3>'+String(i+1).padStart(2,'0')+' / '+E(topic)+'</h3><p>'+task.result.filter(r=>r.topic===topic).map(r=>'《'+E(r.title)+'》记录了'+E(r.excerpt)).join(' ')+'</p><div>'+task.result.filter(r=>r.topic===topic).map(r=>sourceLink(r.doc)).join('')+'</div>').join('')+'<h3>后续核验建议</h3><p>结合对应文件、审批记录及执行凭证进一步核实。归纳结果只反映本次资料，不代替对完整资料范围的审阅。</p></div>')+'</div>';
if(id==='timeline'){const from=task.dateFrom||'',to=task.dateTo||'',rs=rows.filter(r=>(!from||r.date>=from)&&(!to||r.date<=to)).sort((a,b)=>a.date.localeCompare(b.date));return '<div class="card">'+resultToolbar(task)+'<div class="result-tools"><span class="filter-note">日期取自文档事项，不是上传时间</span><div class="row"><input aria-label="开始日期" type="date" data-change="date-from" value="'+from+'"><span class="muted">至</span><input aria-label="结束日期" type="date" data-change="date-to" value="'+to+'">'+A('重置','reset-dates')+'</div></div><div class="cardbody">'+(rs.length?'<div class="timeline">'+rs.map(r=>'<article class="timeline-item"><div class="timeline-date">'+E(r.date)+'</div><h4>'+E(r.title)+'</h4><p>'+E(r.excerpt)+'</p>'+sourceLink(r.doc)+'</article>').join('')+'</div>':noResult())+'</div></div>';}
if(id==='contract'&&w.subtab==='info')return '<div class="card"><div class="panel-tabs"><div class="tabs"><button class="tab" data-action="subtab" data-id="main">条款检查</button><span class="tab active">合同基础信息</span></div></div>'+simpleTable(['合同名称','涉及单位','金额与单位','关键日期','核验'],[...new Map(task.result.map(r=>[r.doc,r])).values()].map(r=>[E(r.title),E(r.unit),E(r.amount),E(r.date),sourceLink(r.doc,'原文')]),true)+'</div>';
if(['risk','contract','bidding'].includes(id))return '<div class="card">'+(id==='contract'?'<div class="panel-tabs"><div class="tabs"><span class="tab active">条款检查</span><button class="tab" data-action="subtab" data-id="info">合同基础信息</button></div></div>':'')+resultToolbar(task,id==='contract'?B(task.report?'查看分析报告':'生成分析报告','contract-report','sm'):id==='bidding'?tag(task.modes.map(m=>({tender:'招标',bid:'投标',joint:'联合'}[m])).join(' + '),'blue'):'')+'<div class="scroll-hint">以下为分析线索。判断与依据需结合原文核验，不等同于已确认审计问题。</div>'+(rows.length?simpleTable(id==='bidding'?['项目 / 单位','检查项','结果','内容摘要','核验']:['文件 / 检查项','判断结果','原文摘录','核验'],rows.map((r,i)=>id==='bidding'?['<b>'+E(r.title)+'</b><div class="hint">'+E(r.unit)+'</div>',E(r.check),tag(r.judgment,'amber'),E(r.excerpt).slice(0,105),A('查看依据','result-detail','data-index="'+task.result.indexOf(r)+'"')]:['<b>'+E(r.check)+'</b><div class="hint">'+E(file(r.doc)?.name)+'</div>',tag(r.judgment,r.judgment==='已提取'?'blue':'amber'),E(r.excerpt).slice(0,130),A('查看依据','result-detail','data-index="'+task.result.indexOf(r)+'"')]),true):noResult())+'</div>';
if(id==='meeting')return meetingResults(task);
if(id==='prepaid')return prepaidResults(task);
if(id==='engineering'){const kind=w.subtab==='parent'?'parent':'duplicate',r=rows.filter(r=>r.kind===kind);return '<div class="card"><div class="panel-tabs"><div class="tabs">'+[['main','重复项目'],['parent','主子项目']].map(([v,n])=>'<button class="tab '+(w.subtab===v?'active':'')+'" data-action="subtab" data-id="'+v+'">'+n+'</button>').join('')+'</div>'+tag('当前文件内部候选','blue')+'</div>'+resultToolbar(task)+'<div class="scroll-hint">分数使用 0–5 分量纲。候选关系不代表已确认事实，不进行跨文件检测。</div>'+(r.length?simpleTable(['项目记录 A','项目记录 B','关系 / 分数','核验'],r.map(x=>[E(x.a),E(x.b),tag(kind==='parent'?'主子关系候选':'疑似重复','amber')+'<div class="hint"><span class="score">'+x.score+'</span> / 5 分</div>',A('原因与源行','result-detail','data-index="'+task.result.indexOf(x)+'"')]),true):noResult())+'</div>';}
if(id==='association'){let rr=rows.filter(r=>!task.refined||r.score>=4.5);return '<div class="card"><div class="cardhead"><div><h3>返回关联候选 '+rr.length+' 组</h3><p class="hint">'+E(task.tableAName)+' ↔ '+E(task.tableBName)+' · '+(task.config.matchMode==='batch'?'批量模式 / 候选上限 '+task.config.cap:'标准模式')+' · 阈值 '+task.config.threshold+' / 5</p></div>'+B(task.refining?'正在筛选…':task.refined?'恢复初始候选':'进一步筛选候选',task.refined?'restore-candidates':'refine','sm',task.refining?'disabled':'')+'</div>'+resultToolbar(task)+(task.refined?'<div class="notice" style="border-radius:0">'+I('check')+'<span>二次筛选：'+task.result.length+' → '+task.result.filter(r=>r.score>=4.5).length+' 组。原结果已保留，可恢复。</span></div>':'')+(rr.length?simpleTable([E(task.tableAName),E(task.tableBName),'判定分数','核验'],rr.map(r=>['<b>'+E(r.a[0])+'</b><div class="hint">'+E(r.a[1])+' · '+r.a[2]+' 万元</div>','<b>'+E(r.b[0])+'</b><div class="hint">'+E(r.b[1])+' · '+r.b[2]+' 万元</div>','<span class="score">'+r.score+'</span> / 5<br>'+tag('关联候选','blue'),A('查看对应记录','result-detail','data-index="'+task.result.indexOf(r)+'"')]),true):noResult())+'<div class="scroll-hint">这里只显示返回的候选，不把其他记录推断为“无关联”。</div></div>';}return '';}
function meetingResults(task){const w=ws(),base=task.result;if(!base.length)return '<div class="card">'+empty('未提取到会议与议题','本次资料中没有可展示的议题。请添加会议纪要并重新分析。','复制配置新建','new-analysis','message')+'</div>';if(w.subtab==='risk'){if(!task.meetingRisk)return '<div class="card">'+empty(task.riskGenerating?'正在生成风险分析报告':'会议议题已整理，可以继续分析风险',task.riskGenerating?'本阶段仅基于已完成的会议结果，不重复处理所有文件。':'报告将基于本次 '+task.successIds.length+' 份已分析纪要，保留会议与议题来源。',task.riskGenerating?null:'生成风险分析报告','meeting-risk','shield')+'</div>';return '<div class="card"><div class="cardhead"><h3>会议风险分析报告</h3><div class="row">'+A('重新生成','meeting-risk')+B(I('download')+'导出报告','download-meeting-risk','sm')+'</div></div><div class="cardbody reading"><div class="eyebrow">MEETING REVIEW</div><h2>决策与执行事项核验线索</h2><p class="muted small">依据本次常规分析 · '+task.successIds.length+' 份纪要 · 报告</p><nav class="row wrap mb mt">'+A('01 决策事项','report-anchor','data-id="report-decisions"')+A('02 核验建议','report-anchor','data-id="report-advice"')+'</nav><h3 id="report-decisions">01 / 关注决策事项的后续落实</h3>'+base.map(r=>'<p>《'+E(r.title)+'》：'+E(r.excerpt)+'</p>'+sourceLink(r.doc)).join('')+'<h3 id="report-advice">02 / 核验建议</h3><p>将纪要中的要求与批准文件、执行记录逐项对照。材料缺失应标记为待补充，不据此直接认定未履行审批或存在违规。</p><div class="quote">请结合原始资料进一步核实，并保留核验记录。</div></div></div>';}
if(w.subtab==='qa')return '<div class="card chat"><div class="cardhead"><div><h3>围绕这些会议继续提问</h3><p class="hint">仅基于本次 '+task.successIds.length+' 份纪要</p></div><div class="row">'+A('保存对话','save-chat')+A('清空','clear-chat')+'</div></div><div class="chat-messages" id="chat-messages">'+(!task.chats.length?'<div class="chat-welcome"><span class="tool-symbol" style="margin:auto">'+I('message')+'</span><h3>把分散的讨论，串成完整的脉络</h3><p class="hint">先点击一个建议问题填入输入框，再发送。</p><div class="suggestions">'+['这些会议讨论了哪些事项？','设备采购预算有哪些调整？','有哪些事项需要进一步核验？'].map(q=>'<button data-action="suggest-question" data-text="'+q+'">'+q+'</button>').join('')+'</div></div>':task.chats.map(m=>'<div class="chat-question">'+E(m.q)+'</div><div class="chat-answer"><div class="row mb">'+I('spark')+'<b>资料助手</b>'+tag('回答','blue')+'</div><p>'+E(m.a)+'</p><div>'+m.sources.map(id=>sourceLink(id)).join('')+'</div></div>').join(''))+(task.chatting?'<p class="hint">正在整理资料中的相关片段…</p>':'')+'</div><form class="chat-input" id="chat-form"><textarea id="chat-question" aria-label="围绕本次会议提问" placeholder="输入围绕本次会议的问题；Enter 发送，Shift+Enter 换行" '+(task.chatting?'disabled':'')+'></textarea>'+B(I('arrow')+'发送','send-chat','primary',task.chatting?'disabled':'')+'</form></div>';
const topics=[...new Set(base.map(r=>r.topic))];if(!topics.includes(w.meetingTopic))w.meetingTopic=topics[0];const rows=base.filter(r=>r.topic===w.meetingTopic&&JSON.stringify(r).includes(resultFilter));return '<div class="meeting-grid"><div class="card"><div class="cardhead"><h3>会议时间轴</h3></div><div class="cardbody"><div class="timeline">'+[...new Map(base.map(r=>[r.doc,r])).values()].sort((a,b)=>a.date.localeCompare(b.date)).map(r=>'<article class="timeline-item"><div class="timeline-date">'+r.date+'</div><button class="link" style="text-align:left" data-action="meeting-date" data-id="'+r.doc+'">'+E(r.title)+'</button></article>').join('')+'</div></div></div><div class="column"><div class="card"><div class="cardhead"><h3>同类议题</h3>'+tag(topics.length+' 组')+'</div><div class="cardbody row wrap">'+topics.map(t=>'<button class="topic-pill '+(w.meetingTopic===t?'active':'')+'" data-action="topic" data-id="'+E(t)+'">'+E(t)+'<small>涉及 '+base.filter(r=>r.topic===t).length+' 次会议</small></button>').join('')+'</div></div><div class="card"><div class="cardhead"><div><h3>议题明细</h3><p class="hint">当前查看：'+E(w.meetingTopic)+' · 金额单位：万元</p></div>'+A('筛选','meeting-filter')+'</div>'+(resultFilter?'<div class="selectionbar">筛选：'+E(resultFilter)+A('清除','clear-result')+'</div>':'')+(rows.length?simpleTable(['日期 / 会议','议题摘录','涉及金额（万元）','来源'],rows.map(r=>[r.date+'<div class="hint">'+E(r.title)+'</div>',E(r.excerpt),E(r.amount.replace(' 万元','')),A('议题详情','meeting-detail','data-index="'+task.result.indexOf(r)+'"')]),true):noResult())+'</div></div></div>';}
function prepaidResults(task){const base=task.base||'';return '<div class="card"><div class="cardhead"><div><h3>'+(task.status==='awaiting'?'确认计费约定，填写计费基数':'费用计算报告')+'</h3><p class="hint">工程监理服务费 · 单位明确，输入与依据一并保留</p></div>'+tag(task.status==='awaiting'?'等待你的输入':'第二阶段完成',task.status==='awaiting'?'amber':'green')+'</div><div class="cardbody"><div class="quote-card"><h4>提取的计费约定</h4><p>'+E((task.result[0]||{}).excerpt||'未提取到计费约定')+'</p>'+(task.result[0]?sourceLink(task.result[0].doc,'查看合同依据'):'')+'</div><div class="notice amber">'+I('help')+'<span>依据本次合同提取的计费约定计算，并保留计费基数、公式和原文来源。</span></div><div class="cost-grid mt"><div class="cost-card"><label class="field-label" for="fee-base">经确认的工程计费基数（元）</label><div class="row"><input id="fee-base" type="number" min=".01" step=".01" aria-label="计费基数，单位元" placeholder="例如 1000000" value="'+E(base)+'" data-input="fee-base" '+(task.status!=='awaiting'?'readonly':'')+' style="width:100%"><span class="muted">元</span></div><p class="hint">由双方确认、用于计算本合同费用的工程金额。</p>'+ (task.status==='awaiting'?B(task.calculating?'正在计算…':'计算并生成报告','calculate-fee','primary w100 mt',task.calculating?'disabled':''):'<div class="hint mt">本次基数已写入任务快照；新基数请复制新建。</div>')+'</div><div class="cost-card"><span class="small muted">计算结果（元）</span><div class="cost-value">'+(task.fee!=null?Number(task.fee).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2}):'等待填写')+'</div><p class="hint">'+(task.fee!=null?Number(base).toLocaleString()+' 元 × 1.5% = '+Number(task.fee).toLocaleString()+' 元':'填写左侧基数，继续完成第二阶段。关闭页面后可从任务中心继续。')+'</p>'+(task.fee!=null?B(I('download')+'下载计算报告','download-fee','sm mt'):'')+'</div></div></div></div>';}
const STATUS={completed:['已完成','green'],running:['运行中','blue'],partial:['部分失败','amber'],awaiting:['待填计费基数','amber'],failed:['执行失败','red'],stopped:['已停止','']};
function tasksPage(){const allRows=state.tasks.filter(t=>(state.taskStatus==='all'||t.status===state.taskStatus)&&(state.taskTool==='all'||t.toolId===state.taskTool)&&t.name.includes(state.taskQuery));state.taskPage=Math.min(state.taskPage||1,Math.max(1,Math.ceil(allRows.length/8)));const rows=allRows.slice((state.taskPage-1)*8,state.taskPage*8);return '<div class="page"><div class="pagehead"><div><div class="eyebrow">ANALYSIS HISTORY</div><h1>任务中心</h1><p>找回每一次分析，继续未完成的工作。</p></div>'+B(I('plus')+'开始新分析','nav-library','primary')+'</div><div class="stats">'+[['全部任务',state.tasks.length],['正在处理',state.tasks.filter(t=>t.status==='running').length],['需要处理',state.tasks.filter(t=>['partial','failed','awaiting'].includes(t.status)).length],['分析完成',state.tasks.filter(t=>t.status==='completed').length]].map(([n,v])=>'<div class="stat"><small>'+n+'</small><strong>'+v+'</strong></div>').join('')+'</div><section class="card"><div class="toolbar taskfilters"><div class="row wrap"><div class="search">'+I('search')+'<input aria-label="搜索任务" placeholder="搜索任务名称" value="'+E(state.taskQuery)+'" data-input="task-query"></div><select aria-label="任务状态" data-change="task-status"><option value="all">全部状态</option>'+Object.entries(STATUS).map(([v,[n]])=>'<option value="'+v+'" '+(state.taskStatus===v?'selected':'')+'>'+n+'</option>').join('')+'</select><select aria-label="工具类型" data-change="task-tool"><option value="all">全部工具</option>'+TOOLS.map(t=>'<option value="'+t.id+'" '+(state.taskTool===t.id?'selected':'')+'>'+t.name+'</option>').join('')+'</select></div>'+B(I('download')+'合并导出','merge-export','sm')+'</div>'+(taskChecked.length?'<div class="selectionbar">已选择 '+taskChecked.length+' 项信息提取任务'+A('清空选择','clear-task-check')+'</div>':'')+(rows.length?simpleTable(['<span class="small">合并</span>','任务名称 / 工具','资料范围','阶段 / 进度','创建时间','操作'],rows.map(t=>['<input type="checkbox" aria-label="合并导出 '+E(t.name)+'" data-change="task-check" data-id="'+t.id+'" '+(taskChecked.includes(t.id)?'checked':'')+' '+(t.toolId!=='extract'||t.status!=='completed'?'disabled title="仅支持已完成且字段相同的信息提取任务"':'')+'>','<button class="filename" data-action="open-task" data-id="'+t.id+'">'+E(t.name)+'</button><div class="hint">'+tool(t.toolId).name+'</div>',t.ids.length+' 份资料',tag(...STATUS[t.status])+(t.status==='running'?'<div class="bar"><i style="width:'+t.progress+'%"></i></div>':'')+'<div class="hint">'+E(t.phase)+'</div>','<span class="muted">'+new Date(t.created).toLocaleString('zh-CN',{hour12:false})+'</span>','<div class="row wrap">'+A(t.status==='awaiting'?'继续填写':t.status==='running'?'查看进度':['failed','stopped'].includes(t.status)?'查看任务':'查看结果','open-task','data-id="'+t.id+'"')+A('详情','task-detail','data-id="'+t.id+'"')+(t.status==='running'?A('停止','stop-task','data-id="'+t.id+'"'):A('删除记录','delete-task','data-id="'+t.id+'"'))+'</div>']),true):empty('还没有符合条件的任务','从资料管理选择工具，执行后即可在这里查看进度、恢复结果。','前往资料管理','nav-library','tasks'))+'<div class="pagination"><span>共 '+allRows.length+' 项 · 第 '+state.taskPage+' / '+Math.max(1,Math.ceil(allRows.length/8))+' 页</span><div class="row">'+B('上一页','task-prev','sm',state.taskPage<=1?'disabled':'')+B('下一页','task-next','sm',state.taskPage*8>=allRows.length?'disabled':'')+'</div></div><div class="scroll-hint">合并导出适用于已完成且字段相同的信息提取任务；删除任务记录不删除源资料。</div></section></div>';}
function templatesPage(){const templates=[...TOOLS.filter(t=>t.id!=='word').map(t=>({id:'sys-'+t.id,name:t.template,toolId:t.id,system:true,prompt:'请依据原始资料，'+t.desc+'。保留可核验来源。'})),...state.templates];return '<div class="page"><div class="pagehead"><div><div class="eyebrow">REUSABLE KNOWLEDGE</div><h1>模板管理</h1><p>系统模板提供起点，个人模板保存你的分析习惯。</p></div>'+B(I('plus')+'新建个人模板','new-template','primary')+'</div><div class="notice mb">'+I('book')+'<span>系统模板只读。你可以复制后调整为个人模板，或在工具中仅应用到本次分析。</span></div><div class="templates-grid">'+templates.map(t=>'<article class="card template-card"><div class="row between"><span class="tool-symbol">'+I(tool(t.toolId).icon)+'</span>'+tag(t.system?'系统模板':'个人模板',t.system?'':'blue')+'</div><h3>'+E(t.name)+'</h3><p>'+tool(t.toolId).desc+'。<br>适用工具：'+tool(t.toolId).name+'</p><div class="row between">'+A(t.system?'查看并复制':'编辑模板','template-detail','data-id="'+t.id+'"')+(t.system?B('使用模板','use-template','sm','data-id="'+t.id+'"'):A('删除','delete-template','data-id="'+t.id+'"'))+'</div></article>').join('')+'</div></div>';}
function openModal(type,data={}){if(!modal)opener=document.activeElement;modal=type;modalData=data;paintModal(true);}
function closeModal(){modal=null;modalData={};$('#modal-root').innerHTML='';document.body.style.overflow='';if(opener&&opener.isConnected)opener.focus();else $('#main')?.focus();}
function modalFrame(title,sub,body,foot='',cls='',flush=false){return '<div class="modal-backdrop"><section class="modal '+cls+'" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="modalhead"><div><h2 id="dialog-title">'+title+'</h2>'+(sub?'<p>'+sub+'</p>':'')+'</div><button class="iconbtn" data-action="close-modal" aria-label="关闭弹窗">'+I('close')+'</button></header><div class="modalbody '+(flush?'flush':'')+'">'+body+'</div>'+(foot?'<footer class="modalfoot">'+foot+'</footer>':'')+'</section></div>';}
function paintModal(focus=false){const prev=document.activeElement,prevId=prev?.id,pos=prev?.selectionStart;$('#modal-root').innerHTML=modalContent();document.body.style.overflow='hidden';if(focus){const el=$('.modal input:not([type=checkbox]):not([disabled]),.modal select,.modal textarea,.modal button');el?.focus();}else if(prevId){const el=document.getElementById(prevId);el?.focus();try{el?.setSelectionRange(pos,pos);}catch{}}}
function modalContent(){const d=modalData;switch(modal){
case 'picker':return pickerModal();
case 'folder-manage':{const docs=selectedDocs(currentTask()?.ids||ws().ids).filter(f=>f.folder===d.folder);return modalFrame('目录资料 · '+E(d.folder),'本目录 '+docs.length+' 份资料均已纳入本次分析。',simpleTable(['资料名称','状态','操作'],docs.map(f=>[E(f.name),tag('可分析','green'),A('查看原文','source','data-id="'+f.id+'"')]),true),B('关闭','close-modal')+(isLocked()?'':B('批量管理本次资料','folder-batch','primary')),'medium');}

case 'source':{const f=file(d.id);return modalFrame(E(f?.name||'资料不存在'),'原文核验 · 资料',documentPreview(d.id,true),B('关闭','close-modal'),'drawer',true);}
case 'assign-bid':return modalFrame('指定项目与文件角色',E(file(d.id)?.name),'<label class="field-label" for="assign-role">选择归属</label><select id="assign-role" class="w100">'+ws().projects.map(p=>'<optgroup label="'+E(p.name)+'"><option value="'+p.id+':tender:0">招标资料</option>'+p.bidders.map((b,i)=>'<option value="'+p.id+':bid:'+i+'">投标单位 · '+E(b.name||'未命名单位')+'</option>').join('')+'</optgroup>').join('')+'</select>',B('取消','close-modal')+B('确认归组','confirm-assign-bid','primary'),'small');
case 'space':return modalFrame('选择资料空间','空间决定资料浏览范围，切换后已选清单仍保留。',SPACE_ORDER.map(s=>'<button class="topic-pill w100 mb '+(state.space===s?'active':'')+'" data-action="set-space" data-id="'+s+'">'+I(s==='个人空间'?'file':'building')+'　'+s+'<small>'+(s==='项目空间'?'市审计局 / 园区改造项目':s==='公共空间'?'市审计局':'我的资料空间')+'</small></button>').join(''),B('取消','close-modal'),'small');
case 'library-selected':return modalFrame('已选资料 · '+state.librarySelected.length+' 份','跨目录与空间保留，打开工具时带入。',selectedDocs(state.librarySelected).map(f=>'<div class="picked-item">'+ficon(f)+'<span>'+E(f.name)+'<small class="muted" style="display:block">'+E(f.space+' / '+f.folder)+'</small></span><button class="iconbtn" data-action="unselect-library" data-id="'+f.id+'" aria-label="取消选择">'+I('close','icon-sm')+'</button></div>').join(''),B('完成','close-modal','primary'),'medium');
case 'prompt':{const c=currentConfig(),readonly=isLocked()||state.toolId==='bidding';return modalFrame('分析要求',readonly?'本次要求只读；系统规则原件不开放修改。':'只修改本次要求，不覆盖系统模板。','<label class="field-label" for="prompt-editor">完整分析要求</label><textarea id="prompt-editor" class="w100" style="min-height:250px" '+(readonly?'readonly':'')+'>'+E(c.prompt)+'</textarea><div class="notice mt">'+I('help')+'<span>编辑后应用于本次分析，也可以另存为个人模板重复使用。</span></div>',B('关闭','close-modal')+(readonly?'':B('应用到本次分析','apply-prompt','primary')),'medium');}
case 'edit-fields':return modalFrame('提取字段','一行一个字段，使用明确的业务名称。','<label class="field-label" for="fields-editor">字段名称</label><textarea id="fields-editor" class="w100" style="min-height:220px" '+(isLocked()?'readonly':'')+'>'+E(currentConfig().fields.join('\n'))+'</textarea><p class="hint">例如：文件主题、涉及单位、金额与单位、关键日期。自定义字段在结果中显示“未提取到”。</p><div id="field-error" class="error"></div>',B('取消','close-modal')+(isLocked()?'':B('应用字段','apply-fields','primary')),'small');
case 'save-template':case 'new-template':case 'template-detail':{const t=d.template||{},system=t.system,create=modal==='new-template',toolId=t.toolId||state.toolId;return modalFrame(system?'查看系统模板':t.id?'编辑个人模板':create?'新建个人模板':'另存为我的模板',system?'系统原件只读，可复制为个人模板。':'个人模板可在对应工具中选择并重复使用。','<div class="field no-margin"><label for="template-name">模板名称</label><input id="template-name" class="w100" value="'+E(t.name||(create?'':currentConfig().template+' · 我的版本'))+'" '+(system?'readonly':'')+'></div><div class="field"><label for="template-tool">适用工具</label><select id="template-tool" class="w100" '+(!create?'disabled':'')+'>'+TOOLS.filter(x=>x.id!=='word').map(x=>'<option value="'+x.id+'" '+(x.id===toolId?'selected':'')+'>'+x.name+'</option>').join('')+'</select></div><div class="field"><label for="template-prompt">分析要求</label><textarea id="template-prompt" class="w100" style="min-height:160px" '+(system?'readonly':'')+'>'+E(t.prompt||(create?'':currentConfig().prompt))+'</textarea></div><div class="error" id="template-error"></div>',B('取消','close-modal')+B(system?'复制为个人模板':'保存模板',system?'copy-template':'commit-template','primary'),'medium');}
case 'lexicon':return modalFrame('我的用词设置','修改会影响后续新任务；已完成任务保留当时词库快照。','<div class="form-grid"><div><label class="field-label" for="stopword-input">停用词 · 不参与词频统计</label><textarea id="stopword-input" class="w100" style="min-height:220px">'+E(state.stopwords.join('\n'))+'</textarea></div><div><label class="field-label" for="newword-input">专有词 · 作为完整词语统计</label><textarea id="newword-input" class="w100" style="min-height:220px">'+E(state.newwords.join('\n'))+'</textarea></div></div><p class="hint">一行一个词语。对词表及新增词执行文本出现次数统计，不连接正式分词服务。</p>',B('取消','close-modal')+B('保存我的词库','save-lexicon','primary'),'medium');
case 'word-detail':{const r=currentTask().result.find(r=>r.word===d.word);return modalFrame('词语：'+E(d.word),r.count+' 次 · 仅显示本次资料中的来源',r.docs.map(id=>'<div class="quote-card"><h4>'+E(file(id).title)+'</h4><p>'+E((file(id).text||'').split('\n').filter(p=>p.includes(d.word)).join('\n')||'词语来自表格。')+'</p>'+sourceLink(id)+'</div>').join(''),B('关闭','close-modal')+B('加入我的停用词','add-stopword','soft','data-word="'+E(d.word)+'"'),'drawer');}
case 'validation':return modalFrame('还差一点，就可以开始','请补齐以下输入，当前配置与资料已保留。','<div class="column">'+d.errors.map(e=>'<div class="notice amber">'+I('help')+'<span>'+E(e)+'</span></div>').join('')+'</div>',B('返回补充','close-modal','primary'),'small');
case 'result-detail':return resultDetailModal(d.index);
case 'meeting-detail':{const r=currentTask().result[d.index];return modalFrame('议题详情',E(r.title)+' · '+r.date,'<div class="quote-card"><h4>'+E(r.topic)+'</h4><p>'+E(r.excerpt)+'</p></div><div class="file-details">参会人员：'+E(r.participants)+'<br>涉及金额（万元）：'+E(r.amount.replace(' 万元',''))+'<br>议题顺序：第 '+r.agenda+' 项<br>来源：'+E(file(r.doc)?.name)+'</div>'+sourceLink(r.doc,'查看完整纪要'),B('返回议题','close-modal'),'drawer');}
case 'upload':return uploadModal();
case 'upload-records':return modalFrame('上传记录','查看上传、解析进度，失败文件可重试。',state.uploads.length?state.uploads.map(u=>'<div class="upload-row"><div class="row between"><span class="filename">'+E(u.name)+'</span>'+tag(u.status,u.status==='解析失败'?'red':u.status==='可分析'?'green':'amber')+'</div><div class="hint">'+E(u.target)+' · '+E(u.time)+'</div>'+(u.status==='解析失败'?A('重试解析','retry-upload','data-id="'+u.id+'"'):'')+'</div>').join(''):empty('还没有上传记录','选择文件或文件夹上传，完成后即可分析。',null,null,'upload'),B('关闭','close-modal')+B('上传资料','upload','primary'),'medium');
case 'attachments':{const f=file(d.id||ws().preview||ws().ids[0]);if(!f)return modalFrame('附件管理','','请先添加并选择一份主文件。',B('关闭','close-modal'),'small');return modalFrame(E(f.name)+' 的附件','移除关联不删除附件原件。',selectedDocs(raAttachmentIds(f)).map(a=>'<div class="picked-item">'+ficon(a)+'<span>'+E(a.name)+'</span>'+A('预览','source','data-id="'+a.id+'"')+A('移除关联','unlink-attachment','data-main="'+f.id+'" data-id="'+a.id+'" '+(isLocked()?'disabled':''))+'</div>').join('')||'<p class="muted small">当前未建立附件关联，不能据此判断合同无需附件。</p>',B('关闭','close-modal')+B('关联已有资料','pick-attachment','primary','data-id="'+f.id+'" '+(isLocked()?'disabled':'')),'medium');}
case 'file-detail':{const f=file(d.id);return modalFrame('资料详情','对原资料的操作与“移出本次分析”不同。','<div class="row">'+ficon(f)+'<h3>'+E(f.name)+'</h3></div><div class="file-details">资料位置：'+E(f.space+' / '+f.folder)+'<br>文件大小：'+E(f.size)+'<br>资料日期：'+E(f.date)+'<br>当前状态：'+(f.local?'等待解析':'可分析 · 资料')+'</div><div class="row">'+B('查看原文','source','','data-id="'+f.id+'"')+B('附件关联','attachments','','data-id="'+f.id+'"')+'</div>',B('移出资料库','delete-file','danger','data-id="'+f.id+'"')+B('关闭','close-modal'),'small');}
case 'confirm':return modalFrame(d.title||'请确认',d.sub||'', '<p style="line-height:1.9;color:#74869d">'+E(d.text)+'</p>',B('取消','close-modal')+B(d.label||'确认',d.action,'primary',d.attrs||''),'small');
case 'text-input':return modalFrame(d.title,'','<label class="field-label" for="modal-text">'+E(d.label||'名称')+'</label><input class="w100" id="modal-text" value="'+E(d.value||'')+'" placeholder="'+E(d.placeholder||'')+'"><p class="error" id="modal-error"></p>',B('取消','close-modal')+B('确认',d.action,'primary'),'small');
case 'export':return modalFrame('导出分析结果','导出范围独立于屏幕筛选；请选择需要保留的范围。','<div class="field no-margin"><label for="export-scope">资料范围</label><select id="export-scope" class="w100"><option value="all">任务全部结果</option>'+currentTask().successIds.map(id=>'<option value="'+id+'" '+(resultScope===id?'selected':'')+'>'+E(file(id)?.name)+'</option>').join('')+'</select></div><div class="field"><label for="export-format">文件格式</label><select id="export-format" class="w100"><option value="json">JSON · 完整结果与本次配置</option><option value="csv">CSV · 表格明细（Excel 可打开）</option></select></div><p class="hint">导出内容保留本次配置与来源，报告可在结果页单独下载。</p>',B('取消','close-modal')+B(I('download')+'导出文件','do-export','primary'),'small');
case 'task-detail':{const t=state.tasks.find(t=>t.id===d.id);return modalFrame(E(t.name),'任务快照 · '+t.id,'<div class="row mb">'+tag(...STATUS[t.status])+tag(tool(t.toolId).name,'blue')+'</div><h3>处理记录</h3><div class="log"><div>创建：'+new Date(t.created).toLocaleString('zh-CN')+'</div><div>当前阶段：'+E(t.phase)+'</div><div>成功 '+(t.successIds?.length||0)+' 份；失败 '+(t.failedIds?.length||0)+' 份</div></div><h3 class="mt">资料范围</h3><div>'+t.ids.map(id=>sourceLink(id)).join('')+'</div><details><summary>本次配置与输入快照</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere;color:#8091a6;font-size:14px;line-height:1.8">'+E(JSON.stringify(t.config,null,2))+'</pre></details>',B('关闭','close-modal')+B('进入任务','open-task','primary','data-id="'+t.id+'"'),'medium');}
case 'contract-report':return modalFrame('合同分析报告','报告生成与导出明细是两个独立操作。','<article class="reading"><h2>合同条款检查报告</h2><p class="muted small">'+E(currentTask().config.template)+'</p>'+currentTask().result.map(r=>'<h3>'+E(r.check)+' · '+E(r.judgment)+'</h3><p>'+E(r.excerpt)+'</p><p>'+E(r.detail)+'</p>'+sourceLink(r.doc)).join('')+'</article>',B('关闭','close-modal')+B('下载报告文本','download-contract','primary'),'drawer');
case 'help':return modalFrame('让第一次使用也有方向','资料整理、分析与原文核验','<div class="column"><div class="review-card"><strong>01　添加资料</strong><p class="small muted">资料管理选中文件后进入工具，或先打开工具再“添加文件”。可从资料库选择文件或目录。</p></div><div class="review-card"><strong>02　确认配置并执行</strong><p class="small muted">默认模板让你直接开始。字段、关注点、项目归组与两表对应均可修改。左侧列表中的可用资料全部参与分析。</p></div><div class="review-card"><strong>03　阅读结果，核验原文</strong><p class="small muted">点击“查看依据 / 原文”回到来源。筛选只影响展示，修改分析配置会复制新建，不覆盖历史结果。</p></div><div class="review-card"><strong>04　任务随时找回</strong><p class="small muted">进度、部分失败、费用续算都能从任务中心继续。已执行任务保留配置与来源，可随时找回处理进度和分析结果。</p></div></div><details><summary>如何评审异常状态</summary><p class="hint">工具右侧“高级设置 → 状态”可选择正常、部分失败或全部失败。费用第二阶段、报告生成、问答采用本地。</p></details><div class="row wrap mt">'+TOOLS.map(t=>B(t.name,'open-tool','sm','data-id="'+t.id+'"')).join('')+'</div>',B('重置数据','reset-demo','danger')+B('开始使用','close-modal','primary'),'medium');
case 'mobile-nav':return modalFrame('工作台导航','','<div class="column">'+B('资料管理','nav-library')+B('任务中心','nav-tasks')+B('模板管理','nav-templates')+TOOLS.map(t=>B(I(t.icon)+t.name,'open-tool','','data-id="'+t.id+'"')).join('')+'</div>',B('关闭','close-modal'),'small');
default:return '';
}}
function resultDetailModal(index){const task=currentTask(),r=task.result[index];if(!r)return '';let body='<div class="row mb">'+tag(r.judgment||'候选关系','amber')+(r.score?'<span class="score">'+r.score+' / 5 分</span>':'')+'</div><h3>'+E(r.check||'候选关系与来源记录')+'</h3><p class="hint">结合本次分析要求与原文核验结果。</p>';if(r.excerpt)body+='<div class="quote-card mt"><h4>原文摘录</h4><p>'+E(r.excerpt)+'</p></div>';body+='<div class="quote-card mt"><h4>分析说明 / 判断依据</h4><p>'+E(r.detail||'请结合原文复核。')+'</p></div>';if(task.toolId==='association')body+='<h4>'+E(task.tableAName)+' · '+E(file(r.doc)?.name)+'</h4>'+simpleTable(file(r.doc).columns,[r.a])+'<h4 class="mt">'+E(task.tableBName)+' · '+E(file(r.other)?.name)+'</h4>'+simpleTable(file(r.other).columns,[r.b])+'<p class="hint">仅展示对应源行，避免载入整张大表。</p>';else if(task.toolId==='engineering')body+=simpleTable(file(r.doc).columns,r.rows);else body+='<h4 class="mt">核验来源</h4><div>'+(r.refs||[r.doc]).map(id=>sourceLink(id)).join('')+'</div>';return modalFrame('分析依据与原文核验',tool(task.toolId).name+' · 本次结果详情',body,B('返回结果','close-modal'),'drawer');}
function pickerModal(){const p=modalData,ds=docsIn(p.space,p.folder,p.query||'').filter(f=>!f.local&&(!p.table||f.rows)&&f.id!==p.main);let pages=Math.max(1,Math.ceil(ds.length/5));p.page=Math.min(p.page,pages);const onPage=ds.slice((p.page-1)*5,p.page*5),folders=p.space==='项目空间'?FOLDERS:p.space==='个人空间'?['全部资料','我的资料']:['全部资料','制度资料'];return modalFrame(p.table?'选择表'+(p.slot==='A'?'一':'二'):p.bid?'添加'+(p.role==='tender'?'招标':'投标')+'文件':p.main?'关联附件':'添加文件','勾选后立即加入本次暂存清单；取消不会改变原有资料。','<div class="picker-layout"><aside class="picker-left"><select aria-label="资料空间" data-change="picker-space">'+options(SPACE_ORDER,p.space)+'</select>'+folders.map(f=>'<button class="folderbtn '+(p.folder===f?'active':'')+'" data-action="picker-folder" data-id="'+E(f)+'">'+I('folder')+f+'</button>').join('')+'</aside><div class="picker-center"><div class="toolbar"><div class="search">'+I('search')+'<input id="picker-query" placeholder="搜索当前范围" aria-label="搜索待添加文件" data-input="picker-query" value="'+E(p.query||'')+'"></div>'+(!p.table?A('加入本目录','picker-directory'):'')+'</div><div class="selectionbar"><div class="row"><input type="checkbox" aria-label="选择当前页文件" data-change="picker-page" '+(onPage.length&&onPage.every(f=>p.selected.includes(f.id))?'checked':'')+' '+(p.table?'disabled':'')+'><span>当前页 '+onPage.length+' 份</span></div>'+(!p.table?A('选择所有页（'+ds.length+'）','picker-all'):'单选')+'</div>'+simpleTable(['选择','文件名称','状态'],onPage.map(f=>['<input type="'+(p.table?'radio':'checkbox')+'" name="picker-file" aria-label="选择 '+E(f.name)+'" data-change="picker-check" data-id="'+f.id+'" '+(p.selected.includes(f.id)?'checked':'')+'>','<div class="row">'+ficon(f)+'<div class="filename">'+E(f.name)+'<div class="file-sub">'+E(f.folder)+'</div></div></div>',tag('可分析','green')]),true)+(ds.length?'':'<div class="empty" style="min-height:200px"><h3>当前范围没有可选文件</h3><p>调整目录或关键词，已选资料保持不变。</p></div>')+'<div class="pagination"><span>'+p.page+' / '+pages+' 页 · '+ds.length+' 份</span><div class="row">'+B('上页','picker-prev','sm',p.page<=1?'disabled':'')+B('下页','picker-next','sm',p.page>=pages?'disabled':'')+'</div></div></div><aside class="picker-right"><h4>本次已选 <span style="color:var(--blue)">'+p.selected.length+'</span></h4><p class="hint mb">含其他目录、空间和页面的选择</p>'+selectedDocs(p.selected).map(f=>'<div class="picked-item"><span>'+E(f.name)+'<small class="muted" style="display:block">'+E(f.space+' / '+f.folder)+'</small></span><button class="iconbtn" aria-label="取消选择 '+E(f.name)+'" data-action="picker-unselect" data-id="'+f.id+'">'+I('close','icon-sm')+'</button></div>').join('')+(!p.selected.length?'<p class="hint">在左侧列表勾选文件</p>':'')+'</aside></div>', '<span class="grow small muted">已选 '+p.selected.length+' 份有效文件 · 自动去重</span>'+B('取消','close-modal')+B(p.table?'确认此表':p.main?'确认关联 '+p.selected.length+' 份':'确认添加 '+p.selected.length+' 份','confirm-picker','primary',p.selected.length?'':'disabled'),'',true);}
function uploadModal(){return modalFrame('上传资料','目标：'+E(state.space+' / '+(state.folder==='全部资料'?'根目录':state.folder)),'<div class="notice mb">'+I('help')+'<span>选择文件或文件夹，上传后自动解析，完成后可加入分析。</span></div><label class="upload-zone" style="display:block" id="upload-drop">'+I('upload')+'<h3>拖入文件，或点击选择</h3><p>支持多选；本地文件会显示为“等待解析”</p><input type="file" multiple id="upload-input"></label><div class="row between mt">'+B('选择文件夹','upload-folder','sm')+'<input type="file" webkitdirectory multiple id="folder-input" style="display:none">'+B('上传与解析阶段','demo-upload','soft sm')+'</div><div id="upload-list">'+(modalData.items||[]).map(u=>'<div class="upload-row"><div class="row between"><span class="filename">'+E(u.name)+'</span>'+tag(u.status,u.status==='解析失败'?'red':u.status==='可分析'?'green':'blue')+'</div><div class="bar"><i style="width:'+u.progress+'%"></i></div>'+ (u.status==='解析失败'?A('重试解析','retry-upload','data-id="'+u.id+'"'):'')+'</div>').join('')+'</div>',B('关闭并保留记录','close-modal')+B('查看上传记录','upload-records','primary'),'medium');}
function startPicker(extra={}){const w=ws();openModal('picker',{space:state.space,folder:'全部资料',page:1,query:'',selected:[...w.ids],...extra});}
function loadSample(){const w=ws(),t=tool(state.toolId);w.ids=[...t.sample];w.preview=w.ids[0];w.taskId=null;w.tab='preview';w.subtab=t.id==='meeting'?'regular':'main';if(t.id==='bidding'){w.unassigned=[];w.projects=[{id:'p1',name:'设备采购项目',tender:['d6'],bidders:[{name:'青禾公司',files:['d7']},{name:'远川公司',files:['d8']}]}];w.modes=['joint'];}if(t.id==='association'){w.tableA='d10';w.tableB='d11';}render();toast('已添加资料，确认配置后即可执行。');}
function syncBidIds(){const w=ws();w.ids=[...new Set([...(w.unassigned||[]),...w.projects.flatMap(p=>[...p.tender,...p.bidders.flatMap(b=>b.files)])])];}
function newAnalysis(){const w=ws(),task=currentTask();if(task){w.config=structuredClone(task.config);if(state.toolId==='extract')w.config.extractionTemplateChoiceVersion=1;w.config.failure='none';w.ids=[...task.ids];w.projects=structuredClone(task.projects);w.modes=[...task.modes];w.tableA=task.tableA;w.tableB=task.tableB;w.tableAName=task.tableAName;w.tableBName=task.tableBName;}w.taskId=null;w.tab='preview';w.subtab=state.toolId==='meeting'?'regular':'main';resultFilter='';resultScope='all';render();toast('已复制配置与资料，原任务结果保留。');}
function openTask(id){const t=state.tasks.find(x=>x.id===id);if(!t)return;state.toolId=t.toolId;const w=ws();w.taskId=t.id;w.ids=[...t.ids];w.config=structuredClone(t.config);w.projects=structuredClone(t.projects);w.modes=[...t.modes];w.tableA=t.tableA;w.tableB=t.tableB;w.tableAName=t.tableAName;w.tableBName=t.tableBName;w.tab='result';w.subtab=t.toolId==='meeting'?'regular':'main';closeModal();nav('tool',t.toolId);}
function getTemplate(id){if(id.startsWith('sys-')){const t=tool(id.slice(4));return{id,name:t.template,toolId:t.id,system:true,prompt:'请依据所选资料，'+t.desc+'。保留原文引用，不补充资料外的事实。'};}return state.templates.find(t=>t.id===id);}
function saveTemplate(){const name=$('#template-name').value.trim(),prompt=$('#template-prompt').value.trim(),tid=$('#template-tool').value;if(!name||!prompt){$('#template-error').textContent='请填写模板名称与分析要求。';return;}if(state.templates.some(t=>t.name===name&&t.id!==modalData.template?.id)){ $('#template-error').textContent='此名称已存在，请换一个名称。';return;}const existing=modalData.template;if(existing&&!existing.system){Object.assign(existing,{name,prompt});}else{state.templates.push({id:'personal-'+Date.now(),toolId:tid,name,prompt,config:state.view==='tool'?structuredClone(ws().config):null});}closeModal();render();toast('个人模板已保存，可在对应工具中选择。');}
function removeWorkFile(id){const w=ws(),before=[...w.ids];w.ids=w.ids.filter(x=>x!==id);if(state.toolId==='bidding'){w.unassigned=(w.unassigned||[]).filter(x=>x!==id);w.projects.forEach(p=>{p.tender=p.tender.filter(x=>x!==id);p.bidders.forEach(b=>b.files=b.files.filter(x=>x!==id));});}if(w.preview===id)w.preview=w.ids[0]||null;render();toast('已移出本次分析，原文件保留。',()=>{w.ids=before;render();});}
function download(name,text,mime='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type:mime})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已生成下载文件。');}
function csvCell(v){let s=typeof v==='object'?JSON.stringify(v):String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function exportRows(task,scope='all'){const rows=(task.result||[]).filter(r=>scope==='all'||r.doc===scope||r.docs?.includes(scope));if(task.toolId==='extract')return [['来源文件',...task.config.fields,'数据性质'],...rows.map(r=>[file(r.doc)?.name,...r.values,'分析结果'])];const keys=[...new Set(rows.flatMap(Object.keys))];return [keys.concat('数据性质'),...rows.map(r=>keys.map(k=>r[k]??'').concat('分析结果'))];}
function doExport(){const task=currentTask(),scope=$('#export-scope').value,format=$('#export-format').value,rs=(task.result||[]).filter(r=>scope==='all'||r.doc===scope||r.docs?.includes(scope));if(format==='json')download(tool(task.toolId).name+'-结果.json',JSON.stringify({notice:'分析结果与本次配置',task:task.name,scope:scope==='all'?'任务全部资料':file(scope)?.name,config:task.config,results:rs},null,2),'application/json;charset=utf-8');else download(tool(task.toolId).name+'-结果.csv','\uFEFF'+exportRows(task,scope).map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');closeModal();}
function reportText(task,kind){let text='文档挖掘助手 · '+kind+'\n任务：'+task.name+'\n模板：'+task.config.template+'\n\n';if(task.toolId==='prepaid')return text+'计费约定：'+task.result[0]?.excerpt+'\n费用类型：'+task.config.feeType+'\n计费基数（元）：'+task.base+'\n费率：1.5%\n计算结果（元）：'+task.fee+'\n来源：'+file(task.result[0]?.doc)?.name;return text+task.result.map(r=>(r.check||r.title)+'\n'+(r.excerpt||'')+'\n'+(r.detail||'需结合原文和执行凭证核验。')+'\n来源：'+file(r.doc)?.name).join('\n\n');}
function sendChat(){const task=currentTask(),input=$('#chat-question'),q=input?.value.trim();if(!q||task.chatting)return;if(q.length>2000){toast('提问请控制在 2000 字以内。');return;}task.chatting=true;render();setTimeout(()=>{task.chatting=false;let rows=task.result.filter(r=>q.includes('预算')?r.excerpt.includes('预算'):true);let answer=rows.length?'基于本次纪要：'+rows.map(r=>r.date+'《'+r.title+'》记载“'+r.excerpt+'”').join(' ')+' 请结合原文与相关执行记录核验。':'当前结果未找到相应事项，不能据此判断会议未讨论该问题。请核对原文或补充资料。';task.chats.push({q,a:answer,sources:[...new Set(rows.map(r=>r.doc))],time:new Date().toISOString()});persist();if(state.view==='tool'&&currentTask()?.id===task.id){render();const pane=$('#chat-messages');if(pane)pane.scrollTop=pane.scrollHeight;$('#chat-question')?.focus();}},900);}
function handleAction(action,el){const id=el?.dataset.id,w=ws();if(action.startsWith('nav-')){closeModal();nav(action.slice(4));return;}switch(action){
case 'open-tool':{closeModal();const wasLibrary=state.view==='library';state.toolId=id;const work=ws();if(wasLibrary&&state.librarySelected.length){work.ids=[...state.librarySelected];work.preview=work.ids[0];work.taskId=null;work.tab='preview';if(id==='bidding'){work.unassigned=[...work.ids];work.projects=[{id:'p1',name:'设备采购项目',tender:[],bidders:[{name:'青禾公司',files:[]},{name:'远川公司',files:[]}]}];}}nav('tool',id);break;}
case 'quick-start':state.toolId='extract';closeModal();nav('tool','extract');loadSample();break;
case 'sample':loadSample();break;
case 'help':openModal('help');break;
case 'mobile-nav':openModal('mobile-nav');break;
case 'close-modal':closeModal();break;
case 'space':openModal('space');break;
case 'set-space':state.space=id;state.folder='全部资料';state.query='';state.page=1;closeModal();render();break;
case 'folder':state.folder=id;state.page=1;state.query='';render();break;
case 'lib-prev':state.page--;render();break;
case 'lib-next':state.page++;render();break;
case 'clear-library':state.query='';state.folder='全部资料';render();break;
case 'library-clear':state.librarySelected=[];render();break;
case 'library-selected':openModal('library-selected');break;
case 'unselect-library':state.librarySelected=state.librarySelected.filter(x=>x!==id);render();paintModal();break;
case 'source':openModal('source',{id});break;
case 'preview':w.preview=id;w.tab='preview';render();break;
case 'show-result':w.tab='result';render();break;
case 'file-detail':openModal('file-detail',{id});break;
case 'new-folder':openModal('text-input',{title:'新建资料目录',label:'目录名称',placeholder:'例如：验收材料',action:'create-folder'});break;
case 'create-folder':{const name=$('#modal-text').value.trim();if(!name||name.includes('/')){$('#modal-error').textContent='请输入有效名称，不含斜杠。';return;}state.customFolders??=[];if(FOLDERS.includes(name)||state.customFolders.includes(name)){$('#modal-error').textContent='目录名称已存在。';return;}state.customFolders.push(name);FOLDERS.push(name);state.folder=name;state.space='项目空间';closeModal();render();toast('已创建目录，可上传资料。');break;}
case 'delete-file':openModal('confirm',{title:'移出资料库',text:'将“'+file(id).name+'”移出资料库。已有任务仍保留来源与配置快照。',label:'确认移出',action:'confirm-delete-file',attrs:'data-id="'+id+'"'});break;
case 'confirm-delete-file':file(id).deleted=true;state.librarySelected=state.librarySelected.filter(x=>x!==id);closeModal();render();toast('已移出资料库。');break;
case 'picker':startPicker();break;
case 'pick-table':startPicker({table:true,slot:el.dataset.slot,selected:w['table'+el.dataset.slot]?[w['table'+el.dataset.slot]]:[]});break;
case 'remove-table':w['table'+el.dataset.slot]=null;w.ids=[w.tableA,w.tableB].filter(Boolean);render();break;
case 'picker-folder':modalData.folder=id;modalData.page=1;paintModal();break;
case 'picker-prev':modalData.page--;paintModal();break;
case 'picker-next':modalData.page++;paintModal();break;
case 'picker-all':{const p=modalData;const ids=docsIn(p.space,p.folder,p.query).filter(f=>!f.local&&f.id!==p.main).map(f=>f.id);p.selected=[...new Set([...p.selected,...ids])];paintModal();break;}
case 'picker-directory':{const p=structuredClone(modalData);modal='directory-range';modalData={picker:p};$('#modal-root').innerHTML=modalFrame('加入当前目录','不会把目录本身计为一份文件。','<p class="small muted mb">选择加入范围：'+E(p.folder)+'；目录加入不受搜索关键词限制。</p><div class="column">'+B('仅当前目录文件','directory-direct')+B('包含全部子目录文件','directory-recursive')+'</div>',B('返回文件选择','return-picker'),'small');$('.modal button')?.focus();break;}
case 'return-picker':{const p=modalData.picker;openModal('picker',p);break;}
case 'directory-direct':case 'directory-recursive':{const p=modalData.picker;const ids=state.docs.filter(f=>!f.deleted&&!f.local&&f.space===p.space&&f.id!==p.main&&(p.folder==='全部资料'?true:action==='directory-direct'?f.folder===p.folder:f.folder===p.folder||f.folder.startsWith(p.folder+'/'))).map(f=>f.id);p.selected=[...new Set([...p.selected,...ids])];openModal('picker',p);break;}
case 'picker-unselect':modalData.selected=modalData.selected.filter(x=>x!==id);paintModal();break;
case 'confirm-picker':{const p=modalData;if(p.table){w['table'+p.slot]=p.selected[0];w.ids=[...new Set([w.tableA,w.tableB].filter(Boolean))];}else if(p.bid){const project=w.projects.find(x=>x.id===p.project);if(p.role==='tender')project.tender=[...p.selected];else project.bidders[p.index].files=[...p.selected];w.unassigned=(w.unassigned||[]).filter(x=>!p.selected.includes(x));syncBidIds();}else if(p.main){raSetAttachmentIds(file(p.main),p.selected);}else{w.ids=[...p.selected];if(state.toolId==='bidding'){w.projects.forEach(x=>{x.tender=x.tender.filter(v=>w.ids.includes(v));x.bidders.forEach(b=>b.files=b.files.filter(v=>w.ids.includes(v)));});const assigned=w.projects.flatMap(x=>[...x.tender,...x.bidders.flatMap(b=>b.files)]);w.unassigned=w.ids.filter(x=>!assigned.includes(x));}w.preview=w.preview&&w.ids.includes(w.preview)?w.preview:w.ids[0];}closeModal();render();toast('已更新资料范围，重复文件自动去重。');break;}
case 'folder-batch':closeModal();manage=true;manageIds=[];render();break;
case 'folder-manage':openModal('folder-manage',{folder:id});break;
case 'manage':manage=!manage;manageIds=[];render();break;
case 'manage-all':manageIds=[...w.ids];render();break;
case 'manage-remove':{if(!manageIds.length){toast('请先勾选需要移出的文件。');return;}const old=[...w.ids];w.ids=w.ids.filter(x=>!manageIds.includes(x));if(!w.ids.includes(w.preview))w.preview=w.ids[0]||null;manageIds=[];manage=false;render();toast('已批量移出本次分析，原资料保留。',()=>{w.ids=old;render();});break;}
case 'remove-file':removeWorkFile(id);break;
case 'edit-fields':openModal('edit-fields');break;
case 'apply-fields':{const fields=$('#fields-editor').value.split('\n').map(x=>x.trim()).filter(Boolean);if(!fields.length||new Set(fields).size!==fields.length){$('#field-error').textContent='请至少保留一个字段，字段名称不能重复。';return;}w.config.fields=fields;closeModal();render();break;}
case 'check-all':w.config.checks=[...tool(state.toolId).checks];render();break;
case 'prompt':openModal('prompt');break;
case 'apply-prompt':{const txt=$('#prompt-editor').value.trim();if(!txt){toast('分析要求不能为空。');return;}w.config.prompt=txt;closeModal();render();toast('已应用到本次分析。');break;}
case 'save-template':openModal('save-template');break;
case 'new-template':openModal('new-template');break;
case 'template-detail':openModal('template-detail',{template:getTemplate(id)});break;
case 'copy-template':{const t=modalData.template;openModal('new-template',{template:{...t,id:null,system:false,name:t.name+' · 我的版本'}});break;}
case 'commit-template':saveTemplate();break;
case 'use-template':{const t=getTemplate(id);state.toolId=t.toolId;const x=ws();if(x.taskId){x.taskId=null;x.tab='preview';}x.config.template=t.name;x.config.prompt=t.prompt;closeModal();nav('tool',t.toolId);break;}
case 'delete-template':openModal('confirm',{title:'删除个人模板',text:'删除个人模板后，既有任务快照保持不变。',action:'confirm-delete-template',attrs:'data-id="'+id+'"'});break;
case 'confirm-delete-template':state.templates=state.templates.filter(t=>t.id!==id);closeModal();render();toast('个人模板已删除。');break;
case 'lexicon':openModal('lexicon');break;
case 'save-lexicon':state.stopwords=[...new Set($('#stopword-input').value.split('\n').map(x=>x.trim()).filter(Boolean))];state.newwords=[...new Set($('#newword-input').value.split('\n').map(x=>x.trim()).filter(Boolean))];closeModal();render();toast('词库已保存，下次执行生效。');break;
case 'word-detail':openModal('word-detail',{word:el.dataset.word});break;
case 'add-stopword':state.stopwords=[...new Set([...state.stopwords,el.dataset.word])];closeModal();persist();toast('已加入我的停用词，当前结果不变，下次执行生效。');break;
case 'attachments':openModal('attachments',{id});break;
case 'pick-attachment':startPicker({main:id,selected:raAttachmentIds(file(id))});break;
case 'unlink-attachment':{const f=file(el.dataset.main),old=raAttachmentIds(f),target=state.view==='tool'&&w.attachmentOverrides&&typeof w.attachmentOverrides==='object'&&!Array.isArray(w.attachmentOverrides)?w.attachmentOverrides:null;if(!raSetAttachmentIds(f,old.filter(x=>x!==id)))return;paintModal();persist();toast('已移除关联，附件原件保留。',()=>{if(target)target[f.id]=[...old];else f.attachments=[...old];persist();if(modal==='attachments')paintModal();});break;}
case 'assign-bid':openModal('assign-bid',{id});break;
case 'confirm-assign-bid':{const [pid,role,index]=$('#assign-role').value.split(':');const p=w.projects.find(p=>p.id===pid),fid=modalData.id;if(role==='tender')p.tender=[...new Set([...p.tender,fid])];else p.bidders[+index].files=[...new Set([...p.bidders[+index].files,fid])];w.unassigned=(w.unassigned||[]).filter(x=>x!==fid);syncBidIds();closeModal();render();break;}
case 'add-project':w.projects.push({id:'p'+Date.now(),name:'新建采购项目',tender:[],bidders:[{name:'',files:[]}]});render();break;
case 'remove-project':{const old=structuredClone(w.projects);w.projects=w.projects.filter(p=>p.id!==id);syncBidIds();render();toast('已移出项目及资料关联，原文件保留。',()=>{w.projects=old;syncBidIds();render();});break;}
case 'add-bidder':w.projects.find(p=>p.id===id).bidders.push({name:'',files:[]});render();break;
case 'remove-bidder':{const p=w.projects.find(p=>p.id===el.dataset.project),old=structuredClone(p.bidders);p.bidders.splice(+el.dataset.index,1);syncBidIds();render();toast('已移出投标单位，原文件保留。',()=>{p.bidders=old;syncBidIds();render();});break;}
case 'pick-bid':{const p=w.projects.find(p=>p.id===el.dataset.project);startPicker({bid:true,project:p.id,role:el.dataset.role,index:+el.dataset.index,selected:[...(el.dataset.role==='tender'?p.tender:p.bidders[+el.dataset.index].files)]});break;}
case 'remove-bidfile':{const p=w.projects.find(p=>p.id===el.dataset.project),a=el.dataset.role==='tender'?p.tender:p.bidders[+el.dataset.index].files,old=[...a];a.splice(a.indexOf(id),1);syncBidIds();render();toast('已移出该角色的资料关联。',()=>{a.splice(0,a.length,...old);syncBidIds();render();});break;}
case 'run':run();break;
case 'new-analysis':newAnalysis();break;
case 'retry-task':{const task=currentTask();run(task);break;}
case 'stop-task':{const task=state.tasks.find(t=>t.id===id)||currentTask();openModal('confirm',{title:'停止任务',text:'停止后保留资料与配置，后续可复制配置重新执行。',label:'停止任务',action:'confirm-stop',attrs:'data-id="'+task.id+'"'});break;}
case 'confirm-stop':{const task=state.tasks.find(t=>t.id===id);clearInterval(runTimers[id]);task.status='stopped';task.phase='用户停止任务';closeModal();render();toast('任务已停止。');break;}
case 'toggle-config':if(state.toolId==='association'){openModal('task-detail',{id:currentTask().id});}else{configExpanded=!configExpanded;render();}break;
case 'full-result':fullResult=!fullResult;render();break;
case 'subtab':w.subtab=id;render();break;
case 'meeting-base':w.subtab='regular';render();break;
case 'meeting-tab':w.subtab=id;render();break;
case 'topic':w.meetingTopic=id;render();break;
case 'meeting-date':w.meetingTopic=file(id).topic;render();toast('已定位该会议所属议题。');break;
case 'meeting-detail':openModal('meeting-detail',{index:+el.dataset.index});break;
case 'meeting-filter':openModal('text-input',{title:'筛选议题明细',label:'会议名称、人员或关键词',value:resultFilter,action:'apply-meeting-filter'});break;
case 'apply-meeting-filter':resultFilter=$('#modal-text').value.trim();closeModal();render();break;
case 'clear-result':resultFilter='';resultScope='all';if(currentTask()){currentTask().dateFrom='';currentTask().dateTo='';}render();break;
case 'reset-dates':currentTask().dateFrom='';currentTask().dateTo='';render();break;
case 'result-detail':openModal('result-detail',{index:+el.dataset.index});break;
case 'meeting-risk':{const task=currentTask();task.riskGenerating=true;task.meetingRisk=false;render();setTimeout(()=>{task.riskGenerating=false;task.meetingRisk=true;persist();if(currentTask()?.id===task.id)render();toast('会议风险报告已生成。');},1000);break;}
case 'report-anchor':document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'center'});break;
case 'suggest-question':$('#chat-question').value=el.dataset.text;$('#chat-question').focus();break;
case 'send-chat':sendChat();break;
case 'save-chat':{const task=currentTask();if(!task.chats.length){toast('先发送一个问题，再保存对话。');return;}download('会议问答-记录.txt','会议问答记录\n\n'+task.chats.map(m=>'问：'+m.q+'\n答：'+m.a+'\n来源：'+m.sources.map(id=>file(id).name).join('、')).join('\n\n'));break;}
case 'clear-chat':if(!currentTask().chats.length){toast('当前还没有对话。');return;}openModal('confirm',{title:'清空本次对话',text:'只清空这次会议分析的问答记录，不影响会议、议题和风险报告。',action:'confirm-clear-chat'});break;
case 'confirm-clear-chat':currentTask().chats=[];closeModal();render();break;
case 'contract-report':{const task=currentTask();if(task.report){openModal('contract-report');break;}if(task.reportGenerating)return;task.reportGenerating=true;toast('正在生成报告，规则结果保持可用。');el.disabled=true;el.textContent='报告生成中…';setTimeout(()=>{task.reportGenerating=false;task.report=true;persist();if(currentTask()?.id===task.id){render();openModal('contract-report');}},900);break;}
case 'download-contract':download('合同分析报告-.txt',reportText(currentTask(),'合同分析报告'));break;
case 'download-meeting-risk':download('会议风险分析-.txt',reportText(currentTask(),'会议风险分析报告'));break;
case 'focus-base':$('#fee-base')?.focus();$('#fee-base')?.scrollIntoView({behavior:'smooth',block:'center'});break;
case 'calculate-fee':{const task=currentTask(),num=+task.base;if(!Number.isFinite(num)||num<=0||num>1e13){toast('请填写大于0且不超过10万亿元的计费基数，单位元。');$('#fee-base')?.focus();return;}if(task.calculating)return;if(!task.successIds.includes('d9')){toast('所选资料未提取到计费约定，请核对合同资料。');return;}task.calculating=true;render();setTimeout(()=>{task.fee=Math.round(num*0.015*100)/100;task.calculating=false;task.status='completed';task.phase='费用计算报告已生成';persist();if(currentTask()?.id===task.id)render();toast('计算报告已生成，基数与约定已保留。');},900);break;}
case 'download-fee':download('费用计算报告-.txt',reportText(currentTask(),'费用计算报告'));break;
case 'refine':{const task=currentTask();task.refining=true;render();setTimeout(()=>{task.refining=false;task.refined=true;persist();if(currentTask()?.id===task.id)render();toast('二次筛选完成，初始候选已保留。');},900);break;}
case 'restore-candidates':currentTask().refined=false;render();toast('已恢复初始候选。');break;
case 'export':openModal('export');break;
case 'do-export':doExport();break;
case 'open-task':openTask(id);break;
case 'task-prev':state.taskPage--;render();break;
case 'task-next':state.taskPage++;render();break;
case 'task-detail':openModal('task-detail',{id});break;
case 'delete-task':openModal('confirm',{title:'删除任务记录',text:'仅删除此浏览器中的任务与结果记录，不删除原资料。正在运行的任务需要先停止。',action:'confirm-delete-task',attrs:'data-id="'+id+'"'});break;
case 'confirm-delete-task':state.tasks=state.tasks.filter(t=>t.id!==id);Object.values(state.work).forEach(x=>{if(x.taskId===id)x.taskId=null;});taskChecked=taskChecked.filter(x=>x!==id);closeModal();render();toast('已删除任务记录，原资料保留。');break;
case 'clear-task-check':taskChecked=[];render();break;
case 'merge-export':{const ts=taskChecked.map(id=>state.tasks.find(t=>t.id===id));if(ts.length<2){toast('请勾选至少两个已完成的信息提取任务。');return;}if(ts.some(t=>JSON.stringify(t.config.fields)!==JSON.stringify(ts[0].config.fields))){toast('所选任务字段不同，请选择字段完全一致的任务。');return;}const rows=[exportRows(ts[0])[0],...ts.flatMap(t=>exportRows(t).slice(1))];download('合并提取结果-.csv','\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');break;}
case 'upload':openModal('upload',{items:[]});break;
case 'upload-folder':$('#folder-input').click();break;
case 'upload-records':openModal('upload-records');break;
case 'demo-upload':demoUpload();break;
case 'retry-upload':{const u=state.uploads.find(u=>u.id===id);u.status='正在解析';u.progress=60;paintModal();setTimeout(()=>{u.status='可分析';u.progress=100;persist();if(modal==='upload'||modal==='upload-records')paintModal();const did='demo-'+u.id;if(!file(did))state.docs.push({id:did,name:u.name,type:'TXT',folder:state.folder==='全部资料'?'根目录':state.folder,space:state.space,size:'1 KB',date:'2026-10-17',title:'上传解析材料',unit:'市审计局',amount:'未提取到',topic:'资料整理',text:'此文件为生成的文字，用于上传、解析失败及重试成功。\\n完成解析后可添加到分析工具。'});persist();toast('解析重试完成，可在资料库查看。');},800);break;}
case 'reset-demo':openModal('confirm',{title:'重置全部数据',text:'将清空当前浏览器保存的任务、个人模板与上传记录，并恢复初始资料。',label:'重置',action:'confirm-reset'});break;
case 'confirm-reset':Object.values(runTimers).forEach(clearInterval);localStorage.removeItem(storageKey);location.href=location.pathname+'#library';location.reload();break;
default:console.warn('Unknown action',action);
}}
function renderKeepFocus(){const active=document.activeElement,key=active?.dataset.input,id=active?.id,pos=active?.selectionStart;render();const next=id?document.getElementById(id):key?$('[data-input="'+key+'"]'):null;if(next){next.focus();try{next.setSelectionRange(pos,pos);}catch{}}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled){e.preventDefault();handleAction(el.dataset.action,el);}});
document.addEventListener('input',e=>{const el=e.target,w=ws();if(el.dataset.rule&&!isLocked()){const [i,key]=el.dataset.rule.split(':');w.config.compareRules[+i][key]=key==='type'?el.value:+el.value;persist();return;}if(el.dataset.config&&!isLocked()){w.config[el.dataset.config]=el.type==='checkbox'?el.checked:el.value;persist();return;}if(el.dataset.work&&!isLocked()){w[el.dataset.work]=el.value;persist();return;}if(el.dataset.project&&el.tagName==='INPUT'){const p=w.projects.find(p=>p.id===el.dataset.project);if(p)p.name=el.value;persist();return;}if(el.dataset.bidder){const [id,i]=el.dataset.bidder.split(':');w.projects.find(p=>p.id===id).bidders[+i].name=el.value;persist();return;}switch(el.dataset.input){
case 'library-query':state.query=el.value;state.page=1;renderKeepFocus();break;
case 'task-query':state.taskQuery=el.value;state.taskPage=1;renderKeepFocus();break;
case 'result-filter':resultFilter=el.value;renderKeepFocus();break;
case 'picker-query':modalData.query=el.value;modalData.page=1;paintModal();break;
case 'fee-base':if(currentTask()?.status==='awaiting'){currentTask().base=el.value;persist();}break;
}});
document.addEventListener('change',e=>{const el=e.target,id=el.dataset.id,w=ws();if(el.id==='upload-input'||el.id==='folder-input'){uploadFiles(el.files);return;}if(el.dataset.config&&!isLocked()){const key=el.dataset.config;w.config[key]=el.type==='checkbox'?el.checked:el.value;if(key==='template'){const t=state.templates.find(t=>t.name===el.value);if(t){const savedTemplate=t.name;w.config={...w.config,...structuredClone(t.config||{}),template:savedTemplate,prompt:t.prompt};}}render();return;}
switch(el.dataset.change){
case 'library-check':state.librarySelected=el.checked?[...new Set([...state.librarySelected,id])]:state.librarySelected.filter(x=>x!==id);render();break;
case 'library-page':{const ids=docsIn(state.space,state.folder,state.query).slice((state.page-1)*7,state.page*7).filter(d=>!d.local).map(d=>d.id);state.librarySelected=el.checked?[...new Set([...state.librarySelected,...ids])]:state.librarySelected.filter(x=>!ids.includes(x));render();break;}
case 'picker-space':modalData.space=el.value;modalData.folder='全部资料';modalData.page=1;paintModal();break;
case 'picker-check':modalData.selected=modalData.table?[id]:el.checked?[...new Set([...modalData.selected,id])]:modalData.selected.filter(x=>x!==id);paintModal();break;
case 'picker-page':{const p=modalData,ids=docsIn(p.space,p.folder,p.query).filter(f=>!f.local&&f.id!==p.main).slice((p.page-1)*5,p.page*5).map(d=>d.id);p.selected=el.checked?[...new Set([...p.selected,...ids])]:p.selected.filter(x=>!ids.includes(x));paintModal();break;}
case 'manage-check':manageIds=el.checked?[...manageIds,id]:manageIds.filter(x=>x!==id);render();break;
case 'risk-check':w.config.checks=el.checked?[...w.config.checks,el.value]:w.config.checks.filter(x=>x!==el.value);render();break;
case 'bid-mode':w.modes=el.checked?[...new Set([...w.modes,el.value])]:w.modes.filter(x=>x!==el.value);render();break;
case 'result-scope':resultScope=el.value;render();break;
case 'display-top':{const n=+el.value;if(n<10||n>500){toast('展示词数需为10–500。');el.value=currentTask().displayTop||currentTask().config.top;return;}currentTask().displayTop=n;render();break;}
case 'date-from':currentTask().dateFrom=el.value;render();break;
case 'date-to':currentTask().dateTo=el.value;render();break;
case 'task-status':state.taskStatus=el.value;state.taskPage=1;render();break;
case 'task-tool':state.taskTool=el.value;state.taskPage=1;render();break;
case 'task-check':taskChecked=el.checked?[...new Set([...taskChecked,id])]:taskChecked.filter(x=>x!==id);render();break;
}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){e.preventDefault();closeModal();return;}if(e.key==='Tab'&&modal){const els=$$('.modal button:not([disabled]),.modal input:not([disabled]),.modal select:not([disabled]),.modal textarea:not([disabled]),.modal a[href]').filter(x=>x.offsetParent!==null),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}if(e.target.id==='chat-question'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();sendChat();}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='chat-form')sendChat();});
document.addEventListener('dragover',e=>{if(e.target.closest('#upload-drop')){e.preventDefault();e.dataTransfer.dropEffect='copy';}});
document.addEventListener('drop',e=>{if(e.target.closest('#upload-drop')){e.preventDefault();uploadFiles(e.dataTransfer.files);}});
function uploadFiles(files){const arr=Array.from(files);if(!arr.length)return;const target=state.space+' / '+state.folder;arr.forEach((f,i)=>{const id='u'+Date.now()+'-'+i,ext=f.name.split('.').pop().toUpperCase(),record={id,name:f.webkitRelativePath||f.name,target,time:new Date().toLocaleString('zh-CN'),status:'上传完成 · 等待解析',progress:100};state.uploads.unshift(record);state.docs.push({id,name:f.name,type:ext.slice(0,5),folder:state.folder==='全部资料'?'根目录':state.folder,space:state.space,size:(f.size/1024).toFixed(1)+' KB',date:new Date().toISOString().slice(0,10),local:true,title:f.name});modalData.items.push(record);});paintModal();persist();toast('已添加 '+arr.length+' 份文件，正在解析。');}
function demoUpload(){if(modalData.demoRunning)return;modalData.demoRunning=true;const record={id:'up'+Date.now(),name:'阶段材料.txt',target:state.space+' / '+state.folder,time:new Date().toLocaleString('zh-CN'),status:'正在上传',progress:15};state.uploads.unshift(record);modalData.items.push(record);paintModal();const states=[['上传完成，等待解析',35],['正在解析',65],['解析失败',100]];let i=0;const timer=setInterval(()=>{[record.status,record.progress]=states[i++];if(i===states.length){clearInterval(timer);if(modal==='upload')modalData.demoRunning=false;persist();}if(modal==='upload'||modal==='upload-records')paintModal();},650);}
route();
